  function openForgotPassword() {
    const email = $('#auth-email')?.value.trim() || '';
    const modal = openModal(`
      ${modalHead('Reset your password')}
      <p class="row-sub" style="margin-bottom:14px">Enter the email on your account. If it matches, we’ll send a secure link that works once for 30 minutes.</p>
      <form id="forgot-password-form" novalidate>
        <div class="form-field">
          <label for="forgot-password-email">Email</label>
          <input type="email" id="forgot-password-email" autocomplete="email" inputmode="email" value="${esc(email)}" required />
        </div>
        <p class="form-error hidden" id="forgot-password-error" role="alert" tabindex="-1"></p>
        <button type="submit" class="btn btn-primary btn-block" id="forgot-password-submit">Send reset link</button>
      </form>
    `, { label: 'Reset your password' });
    const form = modal.querySelector('#forgot-password-form');
    const input = modal.querySelector('#forgot-password-email');
    const error = modal.querySelector('#forgot-password-error');
    const submit = modal.querySelector('#forgot-password-submit');
    form.addEventListener('submit', async (event) => {
      event.preventDefault();
      const value = input.value.trim();
      if (!value || input.validity.typeMismatch) {
        error.textContent = 'Enter a complete email address.';
        error.classList.remove('hidden');
        input.setAttribute('aria-invalid', 'true');
        input.focus({ preventScroll: true });
        return;
      }
      error.classList.add('hidden');
      input.removeAttribute('aria-invalid');
      const resetAction = beginButtonAction(submit, 'Sending…', [input]);
      if (!resetAction) return;
      try {
        const result = await api('/auth/forgot-password', {
          method: 'POST', body: JSON.stringify({ email: value }),
        });
        form.innerHTML = `
          <div class="settings-empty-state" role="status">
            <span aria-hidden="true">${uiIcon('mail')}</span>
            <b>Check your email</b>
            <span>${esc(result.message || 'If that email is registered, a reset link is on its way.')}</span>
          </div>
          <button type="button" class="btn btn-primary btn-block modal-close">Back to log in</button>`;
        form.querySelector('.modal-close').addEventListener('click', () => closeModal(modal));
      } catch (requestError) {
        resetAction();
        error.textContent = requestError.message;
        error.classList.remove('hidden');
        error.focus({ preventScroll: true });
      }
    });
    requestAnimationFrame(() => input.focus({ preventScroll: true }));
    return modal;
  }

  function openPasswordResetLink(rawToken, hash = location.hash) {
    const modal = openModal(`
      ${modalHead('Choose a new password')}
      <p class="row-sub" style="margin-bottom:14px">Use at least 8 characters. Saving signs out any other sessions for this account.</p>
      <form id="reset-password-form" novalidate>
        <div class="form-field"><label for="reset-password-new">New password</label><input type="password" id="reset-password-new" autocomplete="new-password" minlength="8" required /></div>
        <div class="form-field"><label for="reset-password-confirm">Confirm new password</label><input type="password" id="reset-password-confirm" autocomplete="new-password" minlength="8" required /></div>
        <p class="form-error hidden" id="reset-password-error" role="alert" tabindex="-1"></p>
        <button type="submit" class="btn btn-primary btn-block" id="reset-password-submit">Save new password</button>
      </form>
    `, { label: 'Choose a new password' });
    const form = modal.querySelector('#reset-password-form');
    const password = modal.querySelector('#reset-password-new');
    const confirm = modal.querySelector('#reset-password-confirm');
    const error = modal.querySelector('#reset-password-error');
    const submit = modal.querySelector('#reset-password-submit');
    form.addEventListener('submit', async (event) => {
      event.preventDefault();
      let target = null;
      let message = '';
      if (password.value.length < 8) { target = password; message = 'Use at least 8 characters.'; }
      else if (password.value !== confirm.value) { target = confirm; message = 'Those passwords do not match.'; }
      if (message) {
        error.textContent = message;
        error.classList.remove('hidden');
        target.setAttribute('aria-invalid', 'true');
        target.focus({ preventScroll: true });
        return;
      }
      [password, confirm].forEach((input) => input.removeAttribute('aria-invalid'));
      error.classList.add('hidden');
      const resetAction = beginButtonAction(submit, 'Saving…', [password, confirm]);
      if (!resetAction) return;
      try {
        await api('/auth/reset-password', {
          method: 'POST', body: JSON.stringify({ token: rawToken, new_password: password.value }),
        });
        clearAccountActionHash(hash);
        closeModal(modal);
        if (state.token) logout();
        $('#boot-screen')?.classList.add('hidden');
        $('#main-screen')?.classList.add('hidden');
        $('#auth-screen')?.classList.remove('hidden');
        toast('Password updated — log in with your new password', { tone: 'success', duration: 6000 });
        $('#auth-email')?.focus({ preventScroll: true });
      } catch (requestError) {
        resetAction();
        error.textContent = requestError.message;
        error.classList.remove('hidden');
        error.focus({ preventScroll: true });
      }
    });
    requestAnimationFrame(() => password.focus({ preventScroll: true }));
    return modal;
  }

  async function confirmAccountEmailLink(rawToken, kind, hash = location.hash) {
    const changing = kind === 'confirm-email';
    const shell = openDetailLoadShell({
      title: changing ? 'Confirming your new email' : 'Verifying your email',
      copy: 'Checking this secure one-time link…',
      label: changing ? 'Confirming email change' : 'Verifying email',
    });
    if (!shell) return;
    try {
      await api(changing ? '/auth/confirm-email-change' : '/auth/verify-email', {
        method: 'POST', body: JSON.stringify({ token: rawToken }),
      });
      clearAccountActionHash(hash);
      shell.box.removeAttribute('aria-busy');
      shell.box.innerHTML = `
        ${modalHead(changing ? 'Email changed' : 'Email verified')}
        <div class="settings-empty-state" role="status">
          <span aria-hidden="true">${uiIcon('check-circle')}</span>
          <b>${changing ? 'Your new email is ready' : 'Your email is verified'}</b>
          <span>${changing ? 'Log in again with the new address.' : 'You can safely return to Third Shot.'}</span>
        </div>
        <button type="button" class="btn btn-primary btn-block modal-close">Continue</button>`;
      setDialogLabel(shell.box, changing ? 'Email changed' : 'Email verified');
      shell.box.querySelector('.modal-close').addEventListener('click', () => {
        closeModal(shell.modal);
        if (changing && state.token) logout();
        else if (state.token) refreshMe();
      });
    } catch (error) {
      renderDetailLoadError(
        shell,
        error.message || 'This email link is invalid or has expired.',
        () => confirmAccountEmailLink(rawToken, kind, hash),
        'Email link could not be confirmed',
      );
    }
    return shell.modal;
  }

