  async function refreshMe() {
    const generation = invalidateMeRequests();
    const requestOwner = captureAuthenticatedSessionOwner();
    try {
      const data = await api('/me');
      if (generation !== meRequestGeneration
          || !authenticatedSessionOwnerIsCurrent(requestOwner)) return false;
      applyMe(data, {
        reconcileSnapshot: state.snapshotAreaProvisional,
        fromRefresh: true,
      });
      return true;
    } catch { /* logged out */ }
    return false;
  }

  // ---------- Tabs ----------
  function primaryTabScroller(tab) {
    return ['play', 'chat', 'profile'].includes(tab)
      ? $(`#tab-${tab} .tab-scroll`) : null;
  }

  function rememberTabScroll(tab) {
    const scroller = $(`#tab-${tab} .tab-scroll`);
    if (scroller) state.tabScrollPositions[tab] = Math.max(
      0, Number(scroller.scrollTop) || 0,
    );
  }

  function restoreTabScroll(tab, scrollTop = state.tabScrollPositions[tab] || 0) {
    const scroller = $(`#tab-${tab} .tab-scroll`);
    if (!scroller) return;
    const expected = Math.max(0, Number(scrollTop) || 0);
    state.tabScrollPositions[tab] = expected;
    requestAnimationFrame(() => {
      if (scroller.isConnected) scroller.scrollTop = expected;
    });
  }

  function restoreTabAfterRender(tab, renderResult, scrollTop) {
    restoreTabScroll(tab, scrollTop);
    if (renderResult && typeof renderResult.then === 'function') {
      renderResult.then(
        () => restoreTabScroll(tab, scrollTop),
        () => restoreTabScroll(tab, scrollTop),
      );
    }
  }

  function renderTabPreservingScroll(tab, renderer) {
    rememberTabScroll(tab);
    const scrollTop = state.tabScrollPositions[tab] || 0;
    const result = renderer();
    restoreTabAfterRender(tab, result, scrollTop);
    return result;
  }

  function normalizePrimaryFeedLiveRegions() {
    ['play', 'chat', 'profile'].forEach((tab) => {
      const scroller = primaryTabScroller(tab);
      scroller?.removeAttribute('aria-live');
      scroller?.removeAttribute('aria-atomic');
    });
  }

  function scrollTabToTop(tab, { behavior = 'smooth' } = {}) {
    if (tab === 'courts') {
      setCourtSheetSnap('peek');
      return;
    }
    const scroller = $(`#tab-${tab} .tab-scroll`);
    if (!scroller) return;
    state.tabScrollPositions[tab] = 0;
    const reducedMotion = window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
    scroller.scrollTo({ top: 0, behavior: reducedMotion ? 'auto' : behavior });
  }

  function setupTabs() {
    normalizePrimaryFeedLiveRegions();
    ['play', 'chat', 'profile'].forEach((tab) => {
      primaryTabScroller(tab)?.addEventListener(
        'scroll', () => rememberTabScroll(tab), { passive: true },
      );
    });
    document.querySelectorAll('.nav-btn').forEach((btn) => {
      btn.addEventListener('click', () => {
        const tab = btn.dataset.tab;
        if (state.tab === tab) scrollTabToTop(tab);
        else switchTab(tab);
      });
    });
    setupTablistKeyboard($('#play-segments'));
    setupTablistKeyboard($('#chat-segments'));
    $('#profile-edit')?.addEventListener('click', openEditProfile);
    $('#profile-activity')?.addEventListener('click', openActivity);
    $('#profile-settings')?.addEventListener('click', openSettingsHub);
  }

  function switchTab(tab, { preserveOverlayIntent = false, scrollToTop = false } = {}) {
    if (!preserveOverlayIntent) cancelPendingOverlayLoadForNavigation();
    if (state.tab && state.tab !== tab) rememberTabScroll(state.tab);
    const targetScrollTop = scrollToTop ? 0 : state.tabScrollPositions[tab] || 0;
    if (scrollToTop && tab in state.tabScrollPositions) {
      state.tabScrollPositions[tab] = 0;
    }
    state.tab = tab;
    document.querySelectorAll('.nav-btn').forEach((b) => {
      const active = b.dataset.tab === tab;
      b.classList.toggle('active', active);
      if (active) b.setAttribute('aria-current', 'page');
      else b.removeAttribute('aria-current');
    });
    ['courts', 'play', 'chat', 'profile'].forEach((t) => {
      $(`#tab-${t}`).classList.toggle('hidden', t !== tab);
    });
    renderActiveGameBanner();
    if (tab === 'courts') {
      if (state.map) {
        setTimeout(() => state.map.invalidateSize(), 60);
        refreshLookingBanner();
        maybeAutoLocateCourts();
      }
      else ensureMapReady().catch(() => { /* inline retry owns the failure */ });
    }
    let renderResult = null;
    if (tab === 'play') { syncPlayFab(); renderResult = renderPlay({ reuseFresh: true }); }
    if (tab === 'chat') renderResult = renderChat({ reuseFresh: true });
    if (tab === 'profile') renderResult = renderProfile();
    restoreTabAfterRender(tab, renderResult, targetScrollTop);
    if (scrollToTop) requestAnimationFrame(() => scrollTabToTop(tab, { behavior: 'auto' }));
  }

  // One share sheet for every "invite friends" button in the app.
  async function shareInviteLink() {
    if (!state.me) return;
    const candidates = [
      state.activeGame,
      ...(state.playGamesCache?.mine?.items || []),
    ].filter((game, index, items) => (
      game && items.findIndex((item) => Number(item?.id) === Number(game.id)) === index
    ));
    // A public player-invite URL must never reveal a private roster or a live
    // rally. The backend independently validates this destination when the
    // link is opened, so a cancelled/changed session safely loses only the
    // optional game hop while retaining inviter attribution.
    const nextGame = candidates.filter((game) => (
      game.status === 'upcoming'
      && game.visibility === 'open'
      && !game.is_instant
      && new Date(game.scheduled_at).getTime() > Date.now()
    )).sort((a, b) => new Date(a.scheduled_at) - new Date(b.scheduled_at))[0];
    const inviteUrl = new URL(`/u/${state.me.id}`, location.origin);
    if (nextGame) inviteUrl.searchParams.set('game', String(nextGame.id));
    const url = inviteUrl.toString(); // server-rendered OG preview, then auth-safe SPA intent
    const invitationContext = nextGame
      ? `Join me ${fmtDateTime(nextGame.scheduled_at)} at ${nextGame.court?.name || 'the court'}`
      : state.me.home_court_name
        ? `Join me for pickleball at ${state.me.home_court_name}`
        : 'Play pickleball with me';
    const text = `${invitationContext} on Third Shot! 🏓`;
    try {
      if (navigator.share) {
        await navigator.share({ title: 'Third Shot', text, url });
      } else {
        await navigator.clipboard.writeText(`${text} ${url}`);
        toast('Invite link copied', { tone: 'success', icon: 'copy' });
      }
    } catch { /* user cancelled share */ }
  }

  // Pull-to-refresh on the scrolling tabs — installed PWAs don't get the
  // browser's reload gesture, and these feeds otherwise wait on slow polls.
  function setupPullToRefresh() {
    const configs = [
      ['#tab-courts', '#court-list-items', async () => {
        beginCourtContextRefresh('Refreshing courts…');
        return fetchCourtsInView({ surfaceError: true });
      }],
      ['#tab-play', '#play-content', () => renderTabPreservingScroll('play', () => renderPlay())],
      ['#tab-chat', '#chat-content', () => renderTabPreservingScroll('chat', () => renderChat())],
      ['#tab-profile', '#profile-content', () => renderTabPreservingScroll('profile', () => renderProfile())],
    ];
    configs.forEach(([panelSel, scrollSel, refresh]) => {
      const panel = document.querySelector(panelSel);
      const el = document.querySelector(scrollSel);
      if (!panel || !el) return;
      const spinner = document.createElement('div');
      spinner.className = 'ptr-spinner';
      panel.appendChild(spinner);
      let startY = null;
      let armed = false;
      el.addEventListener('touchstart', (e) => {
        startY = el.scrollTop <= 0 ? e.touches[0].clientY : null;
        armed = false;
      }, { passive: true });
      el.addEventListener('touchmove', (e) => {
        if (startY == null) return;
        const dy = e.touches[0].clientY - startY;
        if (dy <= 0 || el.scrollTop > 0) { spinner.style.opacity = '0'; armed = false; return; }
        const pull = Math.min(dy, 110);
        spinner.style.opacity = String(Math.min(pull / 70, 1));
        spinner.style.transform = `translateX(-50%) translateY(${pull * 0.5}px) rotate(${pull * 3}deg)`;
        armed = pull >= 70;
      }, { passive: true });
      el.addEventListener('touchend', async () => {
        startY = null;
        if (!armed) { spinner.style.opacity = '0'; return; }
        armed = false;
        spinner.classList.add('spin');
        try { await refresh(); await refreshMe(); } catch { /* offline */ }
        spinner.classList.remove('spin');
        spinner.style.opacity = '0';
      }, { passive: true });
    });
  }

  // Empty-state CTA buttons: any element with data-goto jumps to the right
  // spot in the app (works inside modals too — closes them first).
  function setupEmptyStateCtas() {
    document.addEventListener('click', (e) => {
      if (e.target.closest('[data-invite-share]')) shareInviteLink();
      const pulseDetails = e.target.closest('[data-play-pulse-details]');
      if (pulseDetails) openPlayPulseDetails();
      const pulseCancel = e.target.closest('[data-play-pulse-cancel]');
      if (pulseCancel) cancelPlayPulse(state.activePlayPulse, pulseCancel);
    });
    document.addEventListener('click', (e) => {
      const btn = e.target.closest('[data-goto]');
      if (!btn) return;
      const target = btn.dataset.goto;
      dismissAllModals(() => {
        if (target === 'casual-play' || target === 'play-soon') {
          if (state.tab !== 'play') switchTab('play');
          const currentCourt = state.presence && state.presence.checked_in ? {
            id: state.presence.court_id,
            name: state.presence.court_name,
          } : null;
          if (currentCourt) openPlayNowCourtPicker({ court: currentCourt });
          else openPlaySoonFlow();
        } else if (target === 'instant-rally') {
          if (state.tab !== 'play') switchTab('play');
          openPlayNowCourtPicker({
            court: state.presence && state.presence.checked_in ? {
              id: state.presence.court_id,
              name: state.presence.court_name,
            } : null,
          });
        } else if (target === 'play-now') {
          if (state.tab !== 'play') switchTab('play');
          openPlaySoonFlow();
        } else if (target === 'on-my-way') {
          if (state.tab !== 'play') switchTab('play');
          openPlaySoonArrivalChoices();
        } else if (target === 'play-pulse') {
          if (state.tab !== 'play') switchTab('play');
          openPlayPulseCourtPicker();
        } else if (target === 'ranked-match' || target === 'new-ranked-game') {
          if (state.tab !== 'play') switchTab('play');
          openRankedMatchFlow();
        } else if (target === 'new-game') {
          if (state.tab !== 'play') switchTab('play');
          openNewGameModal({
            gameType: 'casual', maxPlayers: 6, lockGameType: true, sessionMode: true,
          });
        } else if (target === 'game-flow') {
          if (state.tab !== 'play') switchTab('play');
          openPlaySoonFlow();
        } else if (target === 'compete') {
          setPlaySegment('brackets', { render: false });
          switchTab('play');
        } else if (target === 'log-game') {
          if (state.tab !== 'play') switchTab('play');
          openLogGameSheet();
        } else if (target === 'courts-list') {
          switchTab('courts');
          setCourtSheetSnap('half');
        } else if (target === 'chat-friends') {
          state.chatSeg = 'friends';
          state.peopleMode = 'friends';
          document.querySelectorAll('#chat-segments button').forEach((b) => {
            const active = b.dataset.seg === 'friends';
            b.classList.toggle('active', active);
            b.setAttribute('aria-selected', String(active));
          });
          switchTab('chat');
        } else if (target === 'chat-nearby') {
          state.chatSeg = 'friends';
          state.peopleMode = 'nearby';
          document.querySelectorAll('#chat-segments button').forEach((b) => {
            const active = b.dataset.seg === 'friends';
            b.classList.toggle('active', active);
            b.setAttribute('aria-selected', String(active));
          });
          switchTab('chat');
        } else {
          switchTab(target);
        }
      });
    });
  }

