  function tournamentEstimatedDurationMinutes(t) {
    const supplied = Number(t.estimated_duration_minutes);
    if (Number.isFinite(supplied) && supplied > 0) return supplied;
    const entries = Math.max(2, Number(t.max_entries || t.entry_count) || 2);
    const courts = Math.max(1, Number(t.court_count) || 1);
    const matchMinutes = Math.max(15, Number(t.match_minutes) || 30);
    if (t.format === 'round_robin') {
      const rounds = entries % 2 === 0 ? entries - 1 : entries;
      return rounds * Math.max(1, Math.ceil(Math.floor(entries / 2) / courts)) * matchMinutes;
    }
    let bracketSize = 2;
    while (bracketSize < entries) bracketSize *= 2;
    const roundMatches = [];
    for (let divisor = 2; divisor <= bracketSize; divisor *= 2) {
      roundMatches.push(bracketSize / divisor);
    }
    if (entries >= 4) roundMatches[roundMatches.length - 1] += 1;
    return roundMatches.reduce(
      (total, matchCount) => total + Math.max(1, Math.ceil(matchCount / courts)) * matchMinutes,
      0,
    );
  }

