  function openChallengeSheet(player, court, { onCreated = null } = {}) {
    const modal = openModal(`
      <div class="checkin-sheet">
        <form id="ch-form" novalidate>
        <div class="challenge-hero-icon" aria-hidden="true">${uiIcon('trophy')}</div>
        <h3 style="margin:6px 0 2px">Challenge ${esc(player.display_name)}</h3>
        <p class="row-sub" style="margin-bottom:6px">${playerSkillIdentityHtml(player)}</p>
        <p class="row-sub" style="margin-bottom:18px">Ranked singles at ${esc(court.name)}, starting now. The result will change both players’ ratings.</p>
        <button type="submit" class="btn btn-primary btn-block" id="ch-send" style="padding:16px;margin-bottom:8px">${uiIcon('trophy')} Send challenge</button>
        <button type="button" class="btn-link modal-close btn-block">Maybe later</button>
        </form>
      </div>
    `, { label: `Challenge ${player.display_name} to a ranked match` });
    const formUX = bindModalFormUX(modal, '#ch-send');
    modal.querySelector('#ch-form').addEventListener('submit', async (event) => {
      event.preventDefault();
      formUX.clearError();
      const finish = formUX.startSubmitting('Sending challenge…');
      if (!finish) return;
      try {
        const game = await api(`/users/${player.id}/challenge`, {
          method: 'POST',
          body: JSON.stringify({ court_id: court.id }),
        });
        toast(`Challenge sent to ${player.display_name}`, { tone: 'success', icon: 'trophy' });
        refreshMe();
        transitionModal(modal, () => openGameScreen(game.id));
        try { onCreated?.(game); } catch { /* retained-parent refresh is best-effort */ }
      } catch (err) {
        finish();
        formUX.showError(err.message);
      }
    });
    return modal;
  }

  // Courts without posted hours get one gentle ask per court per device —
  // the check-in moment is when players actually know if the gates are open.
  function maybeAskHours(court) {
    if (court.hours) return;
    const askedKey = `pp_hours_asked_${court.id}`;
    if (localStorage.getItem(askedKey)) return;
    localStorage.setItem(askedKey, '1');
    const modal = openModal(`
      ${modalHead('Know the hours here?')}
      <form id="hp-form" novalidate>
      <p class="row-sub" style="margin-bottom:12px">${esc(court.name)} has no posted hours yet — help players plan their visit.</p>
      <div class="form-field">
        <label for="hp-hours">Court hours</label>
        <input type="text" id="hp-hours" maxlength="120" placeholder="e.g. Daily 6am–10pm, Dawn to dusk" />
      </div>
      <button type="submit" class="btn btn-primary btn-block" id="hp-save">Submit hours</button>
      <button type="button" class="btn-link modal-close btn-block">Skip</button>
      </form>
    `);
    const formUX = bindModalFormUX(modal, '#hp-save');
    modal.querySelector('#hp-form').addEventListener('submit', async (event) => {
      event.preventDefault();
      formUX.clearError();
      const input = modal.querySelector('#hp-hours');
      const hours = input.value.trim();
      if (!hours) {
        formUX.showError('Add the posted hours, or choose Skip.', input);
        return;
      }
      const finish = formUX.startSubmitting('Submitting hours…');
      if (!finish) return;
      try {
        const res = await api(`/courts/${court.id}/suggest`, { method: 'POST', body: JSON.stringify({ hours }) });
        closeModal(modal);
        toast(res.applied_fields.length ? 'Hours added — thanks!' : 'Thanks! It applies once another player confirms', {
          tone: 'success', icon: res.applied_fields.length ? 'clock' : 'check-circle',
        });
      } catch (e) {
        finish();
        formUX.showError(e.message);
      }
    });
    return modal;
  }

  function isCheckedInAtCourt(courtId) {
    return !!(state.presence && state.presence.checked_in
      && Number(state.presence.court_id) === Number(courtId));
  }

  function playNowCourt(value, tag = '') {
    if (!value || typeof value !== 'object') return null;
    const id = safePositiveId(value.id ?? value.court_id);
    if (!id) return null;
    return {
      id,
      name: String(value.name ?? value.court_name ?? 'Pickleball court').slice(0, 120),
      city: String(value.city || '').slice(0, 120),
      latitude: Number.isFinite(Number(value.latitude ?? value.court_latitude))
        ? Number(value.latitude ?? value.court_latitude) : null,
      longitude: Number.isFinite(Number(value.longitude ?? value.court_longitude))
        ? Number(value.longitude ?? value.court_longitude) : null,
      distanceMiles: Number.isFinite(Number(value.distance_miles)) ? Number(value.distance_miles) : null,
      tag: String(tag || value.tag || '').slice(0, 40),
      closed: value.closed === true,
    };
  }

  function playPulseRequestIsAmbiguous(error) {
    const status = Number(error && error.status) || 0;
    return !!(error && (error.isNetworkError || error.data?.retryable === true))
      || status === 408 || status === 425
      || status === 429 || status >= 500;
  }

  function playPulseDirectionsUrl(pulse) {
    if (!pulse) return '';
    return courtDirectionsUrl(pulse.court || {
      id: pulse.courtId,
      name: pulse.courtName,
      city: pulse.courtCity,
      address: pulse.courtAddress,
      latitude: pulse.courtLatitude,
      longitude: pulse.courtLongitude,
    });
  }

  function refreshPlayPulseSurfaces() {
    state.playGamesCache = null;
    refreshLookingBanner();
    if (state.tab === 'play' && state.playSeg === 'games') renderPlay();
    if (state.tab === 'chat' && state.chatSeg === 'friends' && state.peopleMode === 'nearby') renderChat();
  }

  async function declarePlayPulse(court, modal, button, errorEl = null) {
    const selected = playNowCourt(court);
    if (!selected || !button || button.dataset.playPulseCreating === 'true') return null;
    const callerSession = instantRallySession();
    const showError = (message) => {
      if (!errorEl || !document.body.contains(errorEl)) return;
      errorEl.textContent = message;
      errorEl.classList.remove('hidden');
      errorEl.focus({ preventScroll: true });
    };
    if (!callerSession) {
      showError('Sign in again before sharing that you’re free this hour.');
      return null;
    }
    const attempt = pendingPlayPulseCreateAttempt(callerSession.userId, selected.id);
    if (!attempt) {
      showError('Couldn’t save this yet. Free storage on your device and try again.');
      return null;
    }
    const original = button.textContent;
    const modalBox = modal && modal.querySelector('.modal');
    button.dataset.playPulseCreating = 'true';
    button.disabled = true;
    button.setAttribute('aria-busy', 'true');
    button.textContent = 'Sharing that you’re free…';
    modalBox?.setAttribute('aria-busy', 'true');
    errorEl?.classList.add('hidden');
    let record = playPulseCreateInFlight;
    if (!record || record.token !== callerSession.token || record.userId !== callerSession.userId
        || record.courtId !== selected.id || record.attemptId !== attempt.id) {
      record = {
        token: callerSession.token,
        userId: callerSession.userId,
        courtId: selected.id,
        attemptId: attempt.id,
        promise: api('/play/pulse', {
          method: 'PUT',
          body: JSON.stringify({ court_id: selected.id, client_attempt_id: attempt.id }),
        }),
      };
      playPulseCreateInFlight = record;
    }
    try {
      const response = await record.promise;
      if (!instantRallySessionMatches(callerSession)) return null;
      const responsePulse = playPulseFromValue(response && response.pulse);
      if (!responsePulse) {
        const malformed = new Error('We couldn’t confirm Free this hour. Try again.');
        malformed.isNetworkError = true;
        throw malformed;
      }
      const pulse = normalizeActivePlayPulse(responsePulse);
      clearPlayPulseCreateAttempt(callerSession.userId, selected.id, attempt.id);
      if (!pulse) {
        invalidateMeRequests();
        state.activePlayPulse = null;
        if (modal && document.body.contains(modal)) closeModal(modal);
        refreshPlayPulseSurfaces();
        refreshMe().catch(() => {});
        toast('That Free this hour window already ended. Start a new one when you’re still free.');
        return null;
      }
      invalidateMeRequests();
      state.activePlayPulse = pulse;
      refreshPlayPulseSurfaces();
      refreshMe().catch(() => {});
      toast(`You’re free this hour at ${pulse.courtName} · until ${fmtTimeShort(pulse.expiresAt)}`);
      if (modal && document.body.contains(modal) && currentOverlayEntry()?.el === modal) {
        transitionModal(modal, () => openPlayPulseDetails(pulse));
      }
      return pulse;
    } catch (error) {
      if (!instantRallySessionMatches(callerSession)) return null;
      const active = normalizeActivePlayPulse(error?.data?.pulse);
      if (error.code === 'pulse_already_active' && active) {
        invalidateMeRequests();
        state.activePlayPulse = active;
        clearPlayPulseCreateAttempt(callerSession.userId, selected.id, attempt.id);
        refreshPlayPulseSurfaces();
        if (modal && document.body.contains(modal) && currentOverlayEntry()?.el === modal) {
          transitionModal(modal, () => openPlayPulseDetails(active));
        }
        return active;
      }
      const ambiguous = playPulseRequestIsAmbiguous(error);
      if (!ambiguous) {
        clearPlayPulseCreateAttempt(callerSession.userId, selected.id, attempt.id);
      }
      showError(ambiguous
        ? 'Couldn’t confirm Free this hour. Try again.'
        : error.message);
      return null;
    } finally {
      if (playPulseCreateInFlight === record) playPulseCreateInFlight = null;
      if (button && document.body.contains(button)) {
        delete button.dataset.playPulseCreating;
        button.disabled = false;
        button.removeAttribute('aria-busy');
        button.textContent = errorEl && !errorEl.classList.contains('hidden')
          ? 'Try again' : original;
        modalBox?.removeAttribute('aria-busy');
      }
    }
  }

  async function cancelPlayPulse(pulseValue, button = null, modal = null) {
    const pulse = normalizeActivePlayPulse(pulseValue) || playPulseFromValue(pulseValue);
    if (!pulse || (button && button.dataset.playPulseCancelling === 'true')) return false;
    const callerSession = instantRallySession();
    if (!callerSession) return false;
    const original = button && button.textContent;
    if (button) {
      button.dataset.playPulseCancelling = 'true';
      button.disabled = true;
      button.setAttribute('aria-busy', 'true');
      button.textContent = 'Cancelling…';
    }
    try {
      const response = await api(`/play/pulses/${pulse.id}`, { method: 'DELETE' });
      if (!instantRallySessionMatches(callerSession)) return false;
      invalidateMeRequests();
      if (state.activePlayPulse?.id === pulse.id) state.activePlayPulse = null;
      clearPlayPulseCreateAttempt(callerSession.userId, pulse.courtId);
      if (modal && document.body.contains(modal)) closeModal(modal);
      if (response?.cancelled === false && response?.pulse?.end_reason === 'matched') {
        toast('A player already accepted — your quick game was not cancelled.');
      } else if (response?.cancelled === false) {
        toast('That Free this hour post had already ended.');
      } else {
        toast('Free this hour ended');
      }
      refreshPlayPulseSurfaces();
      refreshMe().catch(() => {});
      return true;
    } catch (error) {
      if (!instantRallySessionMatches(callerSession)) return false;
      if (error.code === 'pulse_not_found') {
        invalidateMeRequests();
        if (state.activePlayPulse?.id === pulse.id) state.activePlayPulse = null;
        if (modal && document.body.contains(modal)) closeModal(modal);
        refreshPlayPulseSurfaces();
        refreshMe().catch(() => {});
        toast('That Free this hour post already ended');
        return true;
      }
      toast(error.message);
      return false;
    } finally {
      if (button && document.body.contains(button)) {
        delete button.dataset.playPulseCancelling;
        button.disabled = false;
        button.removeAttribute('aria-busy');
        button.textContent = original;
      }
    }
  }

  function playPulseCommitmentCopy(pulse) {
    const first = String(pulse?.user?.display_name || 'This player').split(/\s+/)[0];
    const until = pulse?.expiresAt ? ` until ${fmtTimeShort(pulse.expiresAt)}` : '';
    return `${first} wants to play at ${pulse?.courtName || 'this court'}${until}. If you join, we’ll set up a casual game and let ${first} know. Only the court is shared, not your location.`;
  }

  async function refreshPlayPulseAcceptAttempt(pulse, attempt, callerSession) {
    const pulseLat = Number(pulse?.courtLatitude);
    const pulseLng = Number(pulse?.courtLongitude);
    const loc = Number.isFinite(pulseLat) && Number.isFinite(pulseLng)
      ? { lat: pulseLat, lng: pulseLng } : committedAreaLatLng();
    if (!loc) return null;
    const looking = await api(`/players/looking?lat=${encodeURIComponent(loc.lat)}&lng=${encodeURIComponent(loc.lng)}&radius=50`);
    if (!instantRallySessionMatches(callerSession)) return null;
    const refreshedPulse = normalizeLookingPulses(looking).find((item) => item.id === pulse.id);
    if (!refreshedPulse || !refreshedPulse.acceptCapability
        || refreshedPulse.courtId !== pulse.courtId) return null;
    const refreshedAttempt = {
      ...attempt,
      acceptCapability: refreshedPulse.acceptCapability,
      capabilityRefreshedAt: Date.now(),
    };
    const storageKey = playPulseAcceptAttemptKey(callerSession.userId, pulse.id);
    if (!storageKey || !persistRecoveryValue(storageKey, JSON.stringify(refreshedAttempt))) {
      const storageError = new Error('Couldn’t save this yet. Free storage on your device and try again.');
      storageError.code = 'retry_storage_unavailable';
      throw storageError;
    }
    return refreshedAttempt;
  }

  async function postPlayPulseAcceptance(pulse, attempt, callerSession) {
    const send = (record) => api(`/play/pulses/${pulse.id}/accept`, {
      method: 'POST',
      body: JSON.stringify({
        accept_capability: record.acceptCapability,
        client_attempt_id: record.id,
      }),
    });
    try {
      return await send(attempt);
    } catch (error) {
      // Exact replay is attempted first. A 404 therefore proves this request
      // did not already create a game; refresh a stale discovery capability
      // and retry once with the same id if the pulse is still discoverable.
      if (error.code !== 'pulse_not_found') throw error;
      const refreshedAttempt = await refreshPlayPulseAcceptAttempt(
        pulse, attempt, callerSession,
      );
      if (!refreshedAttempt) throw error;
      return send(refreshedAttempt);
    }
  }

  async function acceptPlayPulse(pulseValue, button, modal = null, errorEl = null) {
    const pulseRecord = playPulseFromValue(pulseValue);
    const savedAttempt = pulseRecord && readPlayPulseAcceptAttempt(
      state.me && state.me.id, pulseRecord.id,
    );
    // Once an acceptance POST may have crossed the wire, local expiry must not
    // block exact replay: the server can still return the already-created game.
    const activePulse = normalizeActivePlayPulse(pulseRecord);
    const pulse = activePulse || (savedAttempt && pulseRecord
      ? { ...pulseRecord, acceptCapability: savedAttempt.acceptCapability }
      : null);
    if (!pulse || !pulse.acceptCapability || !button
        || button.dataset.playPulseAccepting === 'true') return null;
    const callerSession = instantRallySession();
    const showError = (message) => {
      if (errorEl && document.body.contains(errorEl)) {
        errorEl.textContent = message;
        errorEl.classList.remove('hidden');
        errorEl.focus({ preventScroll: true });
      } else toast(message);
    };
    if (!callerSession) {
      showError('Sign in again before creating the quick game.');
      return null;
    }
    const attempt = pendingPlayPulseAcceptAttempt(
      callerSession.userId, pulse.id, pulse.acceptCapability,
    );
    if (!attempt) {
      showError('Couldn’t save this yet. Free storage on your device and try again.');
      return null;
    }
    const original = button.textContent;
    button.dataset.playPulseAccepting = 'true';
    button.disabled = true;
    button.setAttribute('aria-busy', 'true');
    button.textContent = 'Creating game…';
    modal?.querySelector('.modal')?.setAttribute('aria-busy', 'true');
    errorEl?.classList.add('hidden');
    const key = `${callerSession.userId}:${pulse.id}`;
    let record = playPulseAcceptInFlight.get(key);
    if (!record || record.token !== callerSession.token || record.attemptId !== attempt.id) {
      record = {
        token: callerSession.token,
        attemptId: attempt.id,
        promise: postPlayPulseAcceptance(pulse, attempt, callerSession),
      };
      playPulseAcceptInFlight.set(key, record);
    }
    try {
      const response = await record.promise;
      if (!instantRallySessionMatches(callerSession)) return null;
      const gameId = safePositiveId(response && response.game && response.game.id);
      if (!gameId) {
        const malformed = new Error('We couldn’t confirm the quick game. Try again.');
        malformed.isNetworkError = true;
        throw malformed;
      }
      clearPlayPulseAcceptAttempt(callerSession.userId, pulse.id, attempt.id);
      invalidateMeRequests();
      state.playGamesCache = null;
      refreshLookingBanner();
      refreshMe().catch(() => {});
      toast(`Quick game created at ${pulse.courtName}`);
      if (modal && document.body.contains(modal) && currentOverlayEntry()?.el === modal) {
        transitionModal(modal, () => openGameScreen(gameId));
      } else openGameScreen(gameId);
      if (state.tab === 'chat' && state.chatSeg === 'friends' && state.peopleMode === 'nearby') renderChat();
      return response;
    } catch (error) {
      if (!instantRallySessionMatches(callerSession)) return null;
      const ambiguous = playPulseRequestIsAmbiguous(error);
      if (!ambiguous) {
        clearPlayPulseAcceptAttempt(callerSession.userId, pulse.id, attempt.id);
      }
      if (['pulse_not_found', 'pulse_start_window_closed', 'invalid_accept_capability'].includes(error.code)) {
        refreshLookingBanner();
        if (state.tab === 'chat' && state.chatSeg === 'friends' && state.peopleMode === 'nearby') renderChat();
      }
      showError(ambiguous
        ? 'Couldn’t confirm the game. Try again.'
        : error.message);
      return null;
    } finally {
      if (playPulseAcceptInFlight.get(key) === record) playPulseAcceptInFlight.delete(key);
      if (button && document.body.contains(button)) {
        delete button.dataset.playPulseAccepting;
        button.disabled = false;
        button.removeAttribute('aria-busy');
        button.textContent = errorEl && !errorEl.classList.contains('hidden')
          ? 'Try again' : original;
        modal?.querySelector('.modal')?.removeAttribute('aria-busy');
      }
    }
  }

  function openPlayPulseAcceptConfirmation(pulseValue) {
    const pulseRecord = playPulseFromValue(pulseValue);
    const retry = pulseRecord && readPlayPulseAcceptAttempt(
      state.me && state.me.id, pulseRecord.id,
    );
    const pulse = normalizeActivePlayPulse(pulseRecord) || (retry ? pulseRecord : null);
    if (!pulse) {
      toast('That Free this hour post is no longer active.');
      if (state.tab === 'chat' && state.chatSeg === 'friends' && state.peopleMode === 'nearby') renderChat();
      return null;
    }
    const first = String(pulse.user?.display_name || 'This player').split(/\s+/)[0];
    const modal = openModal(`
      ${modalHead(`Play at ${pulse.courtName}`)}
      <div class="play-pulse-confirm-person">
        ${pulse.user ? avatarHtml(pulse.user, 'sm') : `<span class="play-pulse-avatar" aria-hidden="true">${uiIcon('pickleball')}</span>`}
        <div><b>${esc(first)} can play at ${esc(pulse.courtName)} this hour</b><span>Free until ${esc(fmtTimeShort(pulse.expiresAt))}</span></div>
      </div>
      <p class="play-pulse-commitment">${esc(playPulseCommitmentCopy(pulse))}</p>
      <p class="form-error hidden" id="play-pulse-accept-error" role="alert" tabindex="-1"></p>
      <button type="button" class="btn btn-primary btn-block" id="play-pulse-accept-confirm">${retry ? 'Try again' : 'I’m in'}</button>
      <button type="button" class="btn-link modal-close btn-block">Not now</button>
    `, { label: `Join ${first} at ${pulse.courtName}` });
    const button = modal.querySelector('#play-pulse-accept-confirm');
    button.addEventListener('click', () => acceptPlayPulse(
      pulse, button, modal, modal.querySelector('#play-pulse-accept-error'),
    ));
    return modal;
  }

  function openPlayPulseDetails(pulseValue = state.activePlayPulse) {
    const pulse = normalizeActivePlayPulse(pulseValue);
    if (!pulse) {
      state.activePlayPulse = null;
      toast('Your Free this hour post has ended.');
      refreshPlayPulseSurfaces();
      return null;
    }
    const directions = playPulseDirectionsUrl(pulse);
    const modal = openModal(`
      ${modalHead('Free this hour')}
      <div class="play-pulse-detail-card">
        <span aria-hidden="true">${uiIcon('map-pin')}</span>
        <div><b>${esc(pulse.courtName)}</b><span>Free until ${esc(fmtTimeShort(pulse.expiresAt))}</span></div>
      </div>
      <p class="play-pulse-commitment">Players can see the court you picked and when you’re free. Only the court is shared, not your location. The first player who joins starts a casual game for both of you.</p>
      ${directions ? `<a class="btn btn-secondary btn-block play-pulse-directions" href="${directions}" target="_blank" rel="noopener" aria-label="Directions to ${esc(pulse.courtName)} (opens Maps)">${uiIcon('external')}<span>Directions</span></a>` : ''}
      <button type="button" class="btn btn-danger btn-block" id="play-pulse-cancel-detail">End Free this hour</button>
      <button type="button" class="btn-link modal-close btn-block">Done</button>
    `, { label: `Free this hour at ${pulse.courtName}` });
    modal.querySelector('#play-pulse-cancel-detail').addEventListener('click', (event) => {
      cancelPlayPulse(pulse, event.currentTarget, modal);
    });
    return modal;
  }

  function activePlayPulseBannerHtml(pulseValue = state.activePlayPulse) {
    const pulse = normalizeActivePlayPulse(pulseValue);
    if (!pulse) return '';
    const directions = playPulseDirectionsUrl(pulse);
    return `
      <section class="play-pulse-active" aria-label="Free this hour at ${esc(pulse.courtName)} until ${esc(fmtTimeShort(pulse.expiresAt))}. Only the court is shared, not your location.">
        <button type="button" class="play-pulse-active-main" data-play-pulse-details>
          <span class="play-pulse-active-icon" aria-hidden="true">${uiIcon('map-pin')}</span>
          <span><b>Free this hour at ${esc(pulse.courtName)}</b><small>Until ${esc(fmtTimeShort(pulse.expiresAt))} · court selected</small></span>
          ${uiIcon('chevron-right', 'chev')}
        </button>
        <div class="play-pulse-active-actions">
          ${directions ? `<a href="${directions}" target="_blank" rel="noopener" aria-label="Directions to ${esc(pulse.courtName)} (opens Maps)">${uiIcon('external')}<span>Directions</span></a>` : '<button type="button" data-play-pulse-details>Details</button>'}
          <button type="button" data-play-pulse-cancel>Cancel</button>
        </div>
      </section>`;
  }

  function gameTypeLabel(gameType) {
    return gameType === 'ranked' ? 'Ranked' : 'Casual';
  }

  function gameFormatLabel(maxPlayers) {
    return Number(maxPlayers) === 2 ? 'Singles' : 'Doubles';
  }

  function gameChoiceCardsHtml({ id, name, legend, value, options }) {
    return `
      <fieldset class="game-choice-field" id="${id}">
        <legend>${esc(legend)}</legend>
        <div class="game-choice-grid">
          ${options.map((option) => `
            <label class="game-choice-option">
              <input type="radio" name="${name}" value="${esc(option.value)}" ${String(option.value) === String(value) ? 'checked' : ''} />
              <span class="game-choice-card" data-tone="${esc(option.tone || '')}">
                <span class="game-choice-icon" aria-hidden="true">${option.icon || ''}</span>
                <span><b>${esc(option.label)}</b><small>${esc(option.copy)}</small></span>
              </span>
            </label>`).join('')}
        </div>
      </fieldset>`;
  }

  function gameSetupChoicesHtml(prefix, gameType = 'casual', maxPlayers = 4, lockedType = null) {
    const typeOptions = [
      { value: 'casual', icon: uiIcon('pickleball'), label: 'Casual', copy: 'Play for fun' },
      { value: 'ranked', icon: uiIcon('trophy'), label: 'Ranked', copy: 'Changes match rating', tone: 'ranked' },
    ].filter((option) => !lockedType || option.value === lockedType);
    const setupLabel = lockedType === 'ranked' ? 'Ranked match setup' : 'Game setup';
    const typeLegend = lockedType === 'ranked' ? 'Match type' : 'Game type';
    return `
      <div class="game-setup-choices" aria-label="${setupLabel}">
        ${gameChoiceCardsHtml({
          id: `${prefix}-type`, name: `${prefix}-type`, legend: typeLegend, value: gameType,
          options: typeOptions,
        })}
        ${gameChoiceCardsHtml({
          id: `${prefix}-format`, name: `${prefix}-format`, legend: 'Format', value: Number(maxPlayers) === 2 ? 2 : 4,
          options: [
            { value: 2, icon: '1v1', label: 'Singles', copy: '2 players' },
            { value: 4, icon: '2v2', label: 'Doubles', copy: '4 players' },
          ],
        })}
      </div>`;
  }

  function gameCapacityChoicesHtml(prefix, value = 4) {
    const selected = Math.max(2, Math.min(CASUAL_GAME_MAX_PLAYERS, Number(value) || 4));
    const openPlayers = selected > 4 ? selected : 8;
    const choices = [
      { value: 2, label: 'Singles', copy: '2 players' },
      { value: 4, label: 'Doubles', copy: '4 players' },
      { value: 'open', label: 'Group', copy: `${openPlayers} players` },
    ];
    return `
      <fieldset class="game-choice-field" id="${prefix}-capacity">
        <legend>Format and players</legend>
        <div class="game-capacity-grid">
          ${choices.map((choice) => `
            <label class="game-choice-option">
              <input type="radio" name="${prefix}-capacity" value="${choice.value}" ${choice.value === 'open' ? selected > 4 ? 'checked' : '' : selected === choice.value ? 'checked' : ''} />
              <span class="game-capacity-card"><b>${choice.label}</b><small>${choice.copy}</small></span>
            </label>`).join('')}
        </div>
        <div class="game-capacity-stepper ${selected > 4 ? '' : 'hidden'}" id="${prefix}-open-capacity" role="group" aria-label="Group player capacity">
          <button type="button" data-capacity-adjust="-1" aria-label="One fewer player">−</button>
          <label><span>Players</span><input type="number" id="${prefix}-open-player-count" min="6" max="${CASUAL_GAME_MAX_PLAYERS}" step="1" inputmode="numeric" value="${openPlayers}" /></label>
          <button type="button" data-capacity-adjust="1" aria-label="One more player">＋</button>
        </div>
      </fieldset>`;
  }

  function openGameFlow(options = {}) {
    const allowedModes = ['find', 'start'];
    let mode = allowedModes.includes(options.mode) ? options.mode : 'find';
    let gameType = options.gameType === 'ranked' ? 'ranked' : 'casual';
    // Casual creation is always community-first. Keep a selected court, but
    // route every Casual compatibility call into presence/group planning so
    // no stale deep link can reopen the old mixed Casual-or-Ranked shell.
    if (gameType === 'casual') {
      return options.court
        ? openPlayNowCourtPicker({ court: options.court })
        : openPlaySoonFlow();
    }
    const lockedGameType = 'ranked';
    const requestedMaxPlayers = Number(options.maxPlayers);
    // Ranked entry points are opponent-first and default to singles. Court
    // detail does not need to repeat that default just to stay consistent with
    // the main Ranked launcher; an explicit doubles choice is still preserved.
    let maxPlayers = requestedMaxPlayers === 2 || requestedMaxPlayers === 4
      ? requestedMaxPlayers : lockedGameType === 'ranked' ? 2 : 4;
    const presenceCourt = state.presence && state.presence.checked_in ? {
      id: state.presence.court_id,
      name: state.presence.court_name,
    } : null;
    const preset = playNowCourt(options.court || presenceCourt, options.court ? 'Selected court' : 'Current check-in');
    let selected = preset;
    const modal = openModal(`
      ${modalHead('Find a ranked match', 'trophy')}
      <p class="game-flow-intro">See open ranked matches, play at your court now, or choose a court, time, and players for later.</p>
      <div class="game-flow-modes" id="game-flow-modes" role="tablist" aria-label="Choose what you want to do">
        <button type="button" role="tab" id="game-flow-tab-find" data-game-flow-mode="find" aria-controls="game-flow-panel" aria-selected="${mode === 'find'}" class="${mode === 'find' ? 'active' : ''}"><span aria-hidden="true">${uiIcon('search')}</span> Find</button>
        <button type="button" role="tab" id="game-flow-tab-start" data-game-flow-mode="start" aria-controls="game-flow-panel" aria-selected="${mode === 'start'}" class="${mode === 'start' ? 'active' : ''}"><span aria-hidden="true">${uiIcon('activity')}</span> Start now</button>
      </div>

      <section class="game-flow-court" aria-labelledby="game-flow-court-label">
        <div class="game-flow-section-label" id="game-flow-court-label">Court</div>
        <div class="play-now-selection ${selected ? '' : 'hidden'}" id="game-flow-selection" role="status">
          <span aria-hidden="true">${uiIcon('map-pin')}</span>
          <span class="row-main"><b id="game-flow-selected-name">${selected ? esc(selected.name) : ''}</b><small id="game-flow-selected-city">${selected ? esc(selected.city || 'Selected court') : ''}</small></span>
          <button type="button" class="btn btn-secondary btn-sm" id="game-flow-change-court">Change</button>
        </div>
        <div class="game-flow-court-picker ${selected ? 'hidden' : ''}" id="game-flow-court-picker">
          <label class="sr-only" for="game-flow-court-search">Search courts</label>
          <input type="search" id="game-flow-court-search" placeholder="Search courts…" autocomplete="off" />
          <fieldset class="game-flow-court-fieldset">
            <legend class="sr-only">Choose a court</legend>
            <div class="play-now-courts" id="game-flow-courts" aria-live="polite" aria-busy="true">
              <div class="play-now-loading" role="status"><span class="spinner"></span><span>Finding current, saved, home, and nearby courts…</span></div>
            </div>
          </fieldset>
          <button type="button" class="btn btn-secondary btn-sm hidden" id="game-flow-retry-courts">Try court suggestions again</button>
        </div>
      </section>

      ${gameSetupChoicesHtml('game-flow', gameType, maxPlayers, lockedGameType)}

      <section id="game-flow-panel" class="game-flow-panel" role="tabpanel" aria-labelledby="game-flow-tab-${mode}">
        <div id="game-flow-find" class="${mode === 'find' ? '' : 'hidden'}">
          <div class="game-flow-mode-copy"><b>Ranked matches you can join</b><span>Exact matches appear first. Other open matches stay visible.</span></div>
          <button type="button" class="game-flow-challenge ${maxPlayers === 2 ? '' : 'is-unavailable'}" id="game-flow-challenge" aria-disabled="${maxPlayers !== 2}">
            <span aria-hidden="true">${uiIcon('users')}</span><span><b>Challenge someone you know</b><small id="game-flow-challenge-copy">${maxPlayers === 2 ? 'Choose a friend for ranked singles' : 'Direct challenges are singles only · schedule ranked doubles instead'}</small></span><span class="chev" aria-hidden="true">${uiIcon('chevron-right')}</span>
          </button>
          <div id="game-flow-results" aria-live="polite"></div>
        </div>
        <div id="game-flow-start" class="${mode === 'start' ? '' : 'hidden'}">
          <div class="game-flow-mode-copy"><b>Start at this court now</b><span id="game-flow-start-copy">Choose a court to continue.</span></div>
          <div class="game-flow-confirm-summary" id="game-flow-start-summary"></div>
          <p class="play-now-privacy" id="game-flow-presence-copy"></p>
        </div>
      </section>
      <p class="form-error hidden" id="game-flow-error" role="alert" tabindex="-1"></p>
      <button type="button" class="btn btn-primary btn-block ${mode === 'find' ? 'hidden' : ''}" id="game-flow-primary"></button>
      <button type="button" class="btn btn-secondary btn-block" id="game-flow-plan-later">${uiIcon('calendar')} Plan a ranked match for later</button>
      <button type="button" class="btn-link modal-close btn-block" id="game-flow-dismiss">Cancel</button>
    `, { label: 'Ranked match' });

    const modalBox = modal.querySelector('.modal');
    modal._dismissBlocked = () => modal.dataset.gameFlowCommitting === 'true';
    const modeButtons = [...modal.querySelectorAll('[data-game-flow-mode]')];
    const resultsEl = modal.querySelector('#game-flow-results');
    const pickerEl = modal.querySelector('#game-flow-court-picker');
    const courtRowsEl = modal.querySelector('#game-flow-courts');
    const searchEl = modal.querySelector('#game-flow-court-search');
    const retryEl = modal.querySelector('#game-flow-retry-courts');
    const primary = modal.querySelector('#game-flow-primary');
    const errorEl = modal.querySelector('#game-flow-error');
    const challengeButton = modal.querySelector('#game-flow-challenge');
    const challengeCopy = modal.querySelector('#game-flow-challenge-copy');
    const suggestionsById = new Map();
    let suggestionRows = [];
    let searchTimer = null;
    let searchSeq = 0;
    let suggestionLoadSeq = 0;
    let findLoadSeq = 0;
    let actionSeq = 0;
    let lockedControls = [];

    const actionIsCurrent = (seq, expectedMode) => seq === actionSeq
      && mode === expectedMode
      && document.body.contains(modal)
      && currentOverlayEntry()?.el === modal;
    const lockFlowForCommit = () => {
      modal.dataset.gameFlowCommitting = 'true';
      lockedControls = [...modal.querySelectorAll('button, input')]
        .filter((control) => control !== primary)
        .map((control) => ({ control, disabled: control.disabled }));
      lockedControls.forEach(({ control }) => { control.disabled = true; });
      modalBox?.setAttribute('aria-busy', 'true');
    };
    const unlockFlowAfterCommit = ({ completed = false } = {}) => {
      lockedControls.forEach(({ control, disabled }) => {
        if (document.body.contains(control)) control.disabled = disabled;
      });
      lockedControls = [];
      delete modal.dataset.gameFlowCommitting;
      modalBox?.removeAttribute('aria-busy');
      if (completed && document.body.contains(modal)) {
        modeButtons.forEach((button) => { button.disabled = true; });
        modal.querySelectorAll('input[name="game-flow-type"], input[name="game-flow-format"]')
          .forEach((input) => { input.disabled = true; });
        modal.querySelector('#game-flow-change-court').disabled = true;
      }
    };

    const setupLabel = () => `${gameTypeLabel(gameType)} ${gameFormatLabel(maxPlayers)}`;
    const showError = (message) => {
      errorEl.textContent = message;
      errorEl.classList.remove('hidden');
      errorEl.focus({ preventScroll: true });
    };
    const clearError = () => errorEl.classList.add('hidden');
    const addSuggestion = (value, tag = '') => {
      const item = playNowCourt(value, tag);
      if (!item || suggestionsById.has(item.id)) return;
      suggestionsById.set(item.id, item);
      suggestionRows.push(item);
    };
    if (preset) addSuggestion(preset, preset.tag);
    if (presenceCourt) addSuggestion(presenceCourt, 'Current check-in');
    if (state.me && state.me.home_court_id) addSuggestion({
      id: state.me.home_court_id,
      name: state.me.home_court_name || 'Primary court',
    }, 'Home');

    const syncStartCopy = () => {
      const summary = `${gameTypeLabel(gameType)} · ${gameFormatLabel(maxPlayers)} · ${maxPlayers} players`;
      modal.querySelector('#game-flow-start-summary').innerHTML = `<b>${esc(summary)}</b><span>Open to players at this court</span>`;
      const presence = state.presence && state.presence.checked_in ? state.presence : null;
      const sameCourt = !!(presence && selected && Number(presence.court_id) === selected.id);
      const proximityConfirmed = !!(sameCourt
        && currentInstantRallyPresenceProof(selected.id));
      const presenceCopy = !selected
        ? 'Choose a court first.'
        : selected.closed
          ? `${selected.name} is marked permanently closed. Choose another court.`
        : proximityConfirmed
          ? `Your location at ${selected.name} is confirmed for this start.`
          : sameCourt
            ? `Confirm your current location at ${selected.name} before starting.`
          : presence
            ? `Check in at ${selected.name} first. You’re currently checked in at ${presence.court_name}.`
            : `Check in at ${selected.name} before starting a match there.`;
      modal.querySelector('#game-flow-presence-copy').textContent = presenceCopy;
      modal.querySelector('#game-flow-start-copy').textContent = selected
        ? selected.closed
          ? 'Games can’t be started at a closed court.'
          : `If an identical game is already open, you’ll join it instead of splitting the court.`
        : 'Choose a court to continue.';
      primary.textContent = proximityConfirmed
        ? `${CTA_LABELS.start} ${setupLabel()}`
        : sameCourt
          ? `Confirm court & start · ${setupLabel()}`
          : `Check in to start · ${setupLabel()}`;
      primary.disabled = !selected || !!selected.closed;
    };

    const loadFindGames = async () => {
      const seq = ++findLoadSeq;
      if (mode !== 'find') return;
      if (!selected) {
        resultsEl.innerHTML = '<div class="empty-state" style="padding:14px">Choose a court to see ranked matches you can join.</div>';
        return;
      }
      resultsEl.setAttribute('aria-busy', 'true');
      resultsEl.innerHTML = '<div class="play-now-loading" role="status"><span class="spinner"></span><span>Checking this court for open ranked matches…</span></div>';
      try {
        const detail = await api(`/courts/${selected.id}`);
        if (seq !== findLoadSeq || mode !== 'find' || !document.body.contains(modal)) return;
        selected = { ...selected, closed: !!detail.closed };
        const nowGames = Array.isArray(detail.now_games) ? detail.now_games : (detail.games || []);
        const openGames = nowGames.filter((game) => game.status === 'upcoming'
          && game.game_type === 'ranked'
          && (game.is_joined || Number(game.spots_left) > 0));
        const exact = openGames.filter((game) => game.game_type === gameType
          && Number(game.max_players) === maxPlayers);
        const alternatives = openGames.filter((game) => !exact.includes(game));
        let html = '';
        if (detail.closed) {
          html = '<div class="planner-inline-warning">This court is marked permanently closed, so games can’t be started here.</div>';
        } else if (exact.length) {
          html = `<div class="game-flow-result-label">${esc(setupLabel())} at ${esc(selected.name)}</div>${exact.map((game) => gameCardHtml(game, { compact: true })).join('')}`;
          if (alternatives.length) html += `<details class="game-flow-alternatives"><summary>${alternatives.length} other open match${alternatives.length === 1 ? '' : 'es'}</summary>${alternatives.map((game) => gameCardHtml(game, { compact: true })).join('')}</details>`;
        } else if (alternatives.length) {
          html = `<div class="empty-state game-flow-empty">No ${esc(setupLabel())} ${gameType === 'ranked' ? 'match' : 'play session'} is open right now.</div>
            ${gameType === 'casual'
              ? '<button type="button" class="btn btn-primary btn-block" data-game-flow-casual-group>Gather a group at this court</button>'
              : '<button type="button" class="btn btn-primary btn-block" data-game-flow-switch-start>Start this ranked setup</button>'}
            <div class="game-flow-result-label">Other open ranked matches at ${esc(selected.name)}</div>
            ${alternatives.map((game) => gameCardHtml(game, { compact: true })).join('')}`;
        } else {
          html = `<div class="empty-state game-flow-empty">No open ${gameType === 'ranked' ? 'ranked matches' : 'play sessions'} at ${esc(selected.name)} right now.</div>
            ${gameType === 'casual'
              ? '<button type="button" class="btn btn-primary btn-block" data-game-flow-casual-group>Find people to play</button>'
              : `<button type="button" class="btn btn-primary btn-block" data-game-flow-switch-start>Start ${esc(setupLabel())}</button>`}`;
        }
        resultsEl.innerHTML = html;
        resultsEl.setAttribute('aria-busy', 'false');
        resultsEl.querySelectorAll('[data-game-flow-switch-start]').forEach((button) => {
          button.addEventListener('click', () => setMode('start', { focus: true }));
        });
        resultsEl.querySelectorAll('[data-game-flow-casual-group]').forEach((button) => {
          button.addEventListener('click', () => {
            transitionModal(modal, () => openPlayNowCourtPicker({ court: selected }));
          });
        });
        bindGameButtons(resultsEl, loadFindGames);
        syncStartCopy();
      } catch (error) {
        if (seq !== findLoadSeq || mode !== 'find' || !document.body.contains(modal)) return;
        resultsEl.setAttribute('aria-busy', 'false');
        resultsEl.innerHTML = `<div class="empty-state game-flow-empty">Couldn’t load games at this court.<br>${esc(error.message)}</div><button type="button" class="btn btn-secondary btn-block" id="game-flow-retry-games">Try again</button>`;
        resultsEl.querySelector('#game-flow-retry-games')?.addEventListener('click', loadFindGames);
      }
    };

    const selectCourt = (court) => {
      selected = playNowCourt(court);
      if (!selected) return;
      actionSeq += 1;
      addSuggestion(selected, selected.tag);
      modal.querySelector('#game-flow-selected-name').textContent = selected.name;
      modal.querySelector('#game-flow-selected-city').textContent = selected.city || 'Selected court';
      modal.querySelector('#game-flow-selection').classList.remove('hidden');
      pickerEl.classList.add('hidden');
      clearError();
      syncStartCopy();
      loadFindGames();
    };

    const renderCourtRows = (items = suggestionRows) => {
      courtRowsEl.setAttribute('aria-busy', 'false');
      courtRowsEl.innerHTML = items.length ? items.map((item) => `
        <label class="play-now-court game-flow-court-option">
          <input class="sr-only" type="radio" name="game-flow-court" value="${item.id}" ${selected && selected.id === item.id ? 'checked' : ''} />
          <span class="play-now-court-pin" aria-hidden="true">${uiIcon(selected && selected.id === item.id ? 'check-circle' : 'map-pin')}</span>
          <span class="row-main"><span class="row-title">${esc(item.name)}</span><span class="row-sub">${esc(item.city || 'Pickleball court')}</span></span>
          ${item.tag || item.distanceMiles != null ? `<span class="tag">${esc(item.tag || `${item.distanceMiles} mi`)}</span>` : ''}
        </label>`).join('') : '<div class="empty-state" style="padding:14px">No suggested courts yet. Search by court or city.</div>';
      courtRowsEl.querySelectorAll('input[name="game-flow-court"]').forEach((input) => {
        input.addEventListener('change', () => {
          const court = items.find((item) => item.id === Number(input.value))
            || suggestionsById.get(Number(input.value));
          selectCourt(court);
        });
      });
    };

    const loadSuggestions = async () => {
      const seq = ++suggestionLoadSeq;
      retryEl.classList.add('hidden');
      courtRowsEl.setAttribute('aria-busy', 'true');
      courtRowsEl.innerHTML = '<div class="play-now-loading" role="status"><span class="spinner"></span><span>Finding current, saved, home, and nearby courts…</span></div>';
      const loc = committedAreaLatLng();
      const [saved, nearby] = await Promise.all([
        api('/courts/favorites').catch(() => null),
        loc
          ? api(`/courts?lat=${loc.lat}&lng=${loc.lng}&radius=30&limit=8`).catch(() => null)
          : Promise.resolve({ items: [] }),
      ]);
      if (seq !== suggestionLoadSeq || !document.body.contains(modal)) return;
      (saved && saved.items || []).forEach((item) => addSuggestion(item, 'Saved'));
      (nearby && nearby.items || []).forEach((item) => addSuggestion(
        item, item.distance_miles != null ? `${item.distance_miles} mi` : 'Nearby',
      ));
      if (searchEl.value.trim().length < 2) renderCourtRows();
      if (!saved && !nearby && searchEl.value.trim().length < 2) retryEl.classList.remove('hidden');
    };

    const setMode = (nextMode, { focus = false } = {}) => {
      if (!allowedModes.includes(nextMode)) return;
      if (modal.dataset.gameFlowCommitting === 'true') return;
      if (nextMode !== mode) actionSeq += 1;
      mode = nextMode;
      modeButtons.forEach((button) => {
        const active = button.dataset.gameFlowMode === mode;
        button.classList.toggle('active', active);
        button.setAttribute('aria-selected', String(active));
        button.tabIndex = active ? 0 : -1;
      });
      modal.querySelector('#game-flow-find').classList.toggle('hidden', mode !== 'find');
      modal.querySelector('#game-flow-start').classList.toggle('hidden', mode !== 'start');
      modal.querySelector('#game-flow-panel').setAttribute('aria-labelledby', `game-flow-tab-${mode}`);
      primary.classList.toggle('hidden', mode === 'find');
      clearError();
      syncStartCopy();
      if (mode === 'find') loadFindGames();
      if (focus) {
        const heading = modal.querySelector(`#game-flow-${mode} .game-flow-mode-copy b`);
        heading?.setAttribute('tabindex', '-1');
        heading?.focus({ preventScroll: true });
      }
    };

    modeButtons.forEach((button) => button.addEventListener('click', () => setMode(button.dataset.gameFlowMode)));
    setupTablistKeyboard(modal.querySelector('#game-flow-modes'));
    challengeButton.addEventListener('click', () => {
      if (maxPlayers !== 2) {
        showError('Direct challenges are singles only. Choose Singles, or plan a ranked doubles match for later.');
        return;
      }
      openChildModal(modal, () => openRankedOpponentPicker({
        court: selected, maxPlayers, onCreated: options.onCreated,
      }));
    });
    modal.querySelector('#game-flow-change-court').addEventListener('click', () => {
      actionSeq += 1;
      pickerEl.classList.remove('hidden');
      searchEl.focus({ preventScroll: true });
    });
    retryEl.addEventListener('click', loadSuggestions);
    searchEl.addEventListener('input', () => {
      clearTimeout(searchTimer);
      const query = searchEl.value.trim();
      if (query.length < 2) {
        searchSeq += 1;
        renderCourtRows();
        return;
      }
      searchTimer = setTimeout(async () => {
        const seq = ++searchSeq;
        courtRowsEl.setAttribute('aria-busy', 'true');
        courtRowsEl.innerHTML = '<div class="play-now-loading" role="status"><span class="spinner"></span><span>Searching courts…</span></div>';
        let url = `/courts?q=${encodeURIComponent(query)}&limit=8`;
        if (state.userLoc) url += `&lat=${state.userLoc[0]}&lng=${state.userLoc[1]}`;
        try {
          const response = await api(url);
          if (seq !== searchSeq || searchEl.value.trim() !== query || !document.body.contains(modal)) return;
          const items = (response.items || []).map((item) => playNowCourt(
            item, item.distance_miles != null ? `${item.distance_miles} mi` : '',
          )).filter(Boolean);
          items.forEach((item) => suggestionsById.set(item.id, item));
          renderCourtRows(items);
        } catch {
          if (seq !== searchSeq || searchEl.value.trim() !== query || !document.body.contains(modal)) return;
          courtRowsEl.setAttribute('aria-busy', 'false');
          renderError(courtRowsEl, 'Couldn’t search courts. Check your connection and try again.', () => {
            searchEl.dispatchEvent(new Event('input', { bubbles: true }));
            requestAnimationFrame(() => searchEl.focus({ preventScroll: true }));
          });
        }
      }, 250);
    });
    modal.querySelectorAll('input[name="game-flow-type"]').forEach((input) => input.addEventListener('change', () => {
      actionSeq += 1;
      gameType = input.value === 'ranked' ? 'ranked' : 'casual';
      clearError();
      syncStartCopy();
      loadFindGames();
    }));
    modal.querySelectorAll('input[name="game-flow-format"]').forEach((input) => input.addEventListener('change', () => {
      actionSeq += 1;
      maxPlayers = Number(input.value) === 2 ? 2 : 4;
      challengeButton.setAttribute('aria-disabled', String(maxPlayers !== 2));
      challengeButton.classList.toggle('is-unavailable', maxPlayers !== 2);
      challengeCopy.textContent = maxPlayers === 2
        ? 'Choose a friend for ranked singles'
        : 'Direct challenges are singles only · plan ranked doubles for later';
      clearError();
      syncStartCopy();
      loadFindGames();
    }));
    const confirmSelectedCourtIsOpen = async () => {
      const courtId = selected && selected.id;
      if (!courtId) return false;
      const detail = await api(`/courts/${courtId}`);
      if (!selected || selected.id !== courtId || !document.body.contains(modal)) return false;
      selected = {
        ...selected,
        closed: !!detail.closed,
        latitude: Number.isFinite(Number(detail.latitude)) ? Number(detail.latitude) : selected.latitude,
        longitude: Number.isFinite(Number(detail.longitude)) ? Number(detail.longitude) : selected.longitude,
      };
      syncStartCopy();
      if (selected.closed) throw new Error(`${selected.name} is marked permanently closed. Choose another court.`);
      return true;
    };
    modal.querySelector('#game-flow-plan-later').addEventListener('click', () => {
      transitionModal(modal, () => openNewGameModal({
        court: selected,
        gameType: 'ranked',
        maxPlayers,
        lockGameType: true,
        rankedMatchMode: true,
        setupCarried: true,
        onCreated: options.onCreated,
      }));
    });
    primary.addEventListener('click', async () => {
      if (!selected) {
        showError('Choose a court first.');
        pickerEl.classList.remove('hidden');
        searchEl.focus({ preventScroll: true });
        return;
      }
      if (mode !== 'start' || primary.dataset.gameFlowStarting === 'true') return;
      if (selected.closed) {
        showError('This court is marked permanently closed. Choose another court.');
        return;
      }
      const callerSession = instantRallySession();
      if (!callerSession) {
        showError('Sign in again before starting a game.');
        return;
      }
      const action = ++actionSeq;
      let commitLocked = false;
      primary.dataset.gameFlowAction = String(action);
      primary.dataset.gameFlowStarting = 'true';
      primary.disabled = true;
      primary.setAttribute('aria-busy', 'true');
      clearError();
      try {
        primary.textContent = 'Checking court…';
        if (!await confirmSelectedCourtIsOpen()) return;
        if (!actionIsCurrent(action, 'start')) return;
        if (!isCheckedInAtCourt(selected.id)
            || !currentInstantRallyPresenceProof(selected.id)) {
          const checkInCourt = { ...selected };
          primary.textContent = `Check in at ${selected.name}…`;
          openChildModal(modal, () => openCheckInSheet(checkInCourt, () => {
            if (!instantRallySessionMatches(callerSession)
                || !document.body.contains(modal)
                || Number(selected?.id) !== Number(checkInCourt.id)) return;
            primary.click();
          }, { defaultLooking: true, presenceIntent: 'instant_rally' }));
          return;
        }
        lockFlowForCommit();
        commitLocked = true;
        primary.textContent = `Starting ${setupLabel()}…`;
        const result = await startInstantRally(null, {
          expectedCourtId: selected.id,
          gameType,
          maxPlayers,
          fromModal: modal,
          onError: (error, retrySafely) => showError(retrySafely
            ? 'We couldn’t confirm the game. Try again — we won’t create a duplicate.'
            : error.message),
        });
        if (result) {
          try { options.onCreated?.(result); } catch { /* retained-parent refresh is best-effort */ }
          fetchCourtsInView();
        }
      } catch (error) {
        if (instantRallySessionMatches(callerSession)
            && actionIsCurrent(action, 'start')) showError(error.message);
      } finally {
        if (commitLocked && document.body.contains(modal)) {
          unlockFlowAfterCommit();
        }
        if (primary && document.body.contains(primary)
            && primary.dataset.gameFlowAction === String(action)) {
          delete primary.dataset.gameFlowAction;
          delete primary.dataset.gameFlowStarting;
          primary.disabled = !selected || !!selected.closed;
          primary.removeAttribute('aria-busy');
          syncStartCopy();
          if (mode === 'start' && !errorEl.classList.contains('hidden')) {
            primary.textContent = 'Try again';
          }
        }
      }
    });
    modal._cleanupFns.push(() => {
      clearTimeout(searchTimer);
      actionSeq += 1;
      unlockFlowAfterCommit();
      delete modal._dismissBlocked;
      findLoadSeq += 1;
      suggestionLoadSeq += 1;
      searchSeq += 1;
    });
    syncStartCopy();
    setMode(mode);
    loadSuggestions();
    return modal;
  }

  async function checkInAndStartRally(court, modal, button, errorEl = null) {
    const selected = playNowCourt(court);
    if (!selected || !button || button.dataset.playNowStarting === 'true') return null;
    const original = button.textContent;
    const modalBox = modal && modal.querySelector('.modal');
    const showError = (message) => {
      if (!errorEl || !document.body.contains(errorEl)) return;
      errorEl.textContent = message;
      errorEl.classList.remove('hidden');
      errorEl.focus({ preventScroll: true });
    };
    const callerSession = instantRallySession();
    if (!callerSession) {
      showError('Sign in again before checking in.');
      return null;
    }
    button.dataset.playNowStarting = 'true';
    button.disabled = true;
    button.setAttribute('aria-busy', 'true');
    button.textContent = 'Checking you in…';
    modalBox?.setAttribute('aria-busy', 'true');
    errorEl?.classList.add('hidden');
    try {
      button.textContent = 'Confirming your location…';
      const presenceLocation = await freshCourtPresenceLocation(selected);
      if (!instantRallySessionMatches(callerSession)) return null;
      button.textContent = 'Checking you in…';
      const checkedIn = await api(`/courts/${selected.id}/checkin`, {
        method: 'POST',
        body: JSON.stringify({
          looking_for_game: true,
          presence_intent: 'instant_rally',
          presence_location: presenceLocation,
        }),
      });
      if (!instantRallySessionMatches(callerSession)) return null;
      // The check-in POST is authoritative even before the next /me poll. This
      // lets the rally request follow immediately without a redundant round trip.
      applyAuthoritativeCheckIn(selected, checkedIn, true);
      button.textContent = 'Starting your pickup game…';
      const result = await startInstantRally(null, {
        expectedCourtId: selected.id,
        fromModal: modal,
        onError: (error, retrySafely) => {
          showError(retrySafely
            ? 'We couldn’t confirm the game. Your check-in is saved; try again.'
            : error.message);
        },
      });
      if (!instantRallySessionMatches(callerSession)) return null;
      if (!result) {
        refreshMe().catch(() => { /* keep the confirmed local presence while offline */ });
        return null;
      }
      fetchCourtsInView();
      return result;
    } catch (error) {
      if (!instantRallySessionMatches(callerSession)) return null;
      showError(error.message);
      return null;
    } finally {
      if (button && document.body.contains(button)) {
        delete button.dataset.playNowStarting;
        button.disabled = false;
        button.removeAttribute('aria-busy');
        button.textContent = errorEl && !errorEl.classList.contains('hidden')
          ? 'Try again' : original;
        modalBox?.removeAttribute('aria-busy');
      }
    }
  }

