      const entries = Number(modal.querySelector('#tc-max').value) || 0;
      const courts = Math.max(1, Number(modal.querySelector('#tc-court-count').value) || 1);
      const matchMinutes = Math.max(15, Number(modal.querySelector('#tc-match-minutes').value) || 30);
      const rounds = entries % 2 === 0 ? entries - 1 : entries;
      const matches = entries * (entries - 1) / 2;
      const wavesPerRound = Math.ceil(Math.floor(entries / 2) / courts);
      estimate.textContent = `${entries} players · ${matches} matches across ${rounds} rounds · about ${fmtDuration(rounds * wavesPerRound * matchMinutes)}`;
