    const formUX = bindModalFormUX(modal, '#te-save');
    bindModalDiscardConfirmation(modal, {
      isDirty: formUX.isDirty,
      title: 'Discard tournament changes?',
      message: 'The tournament details you changed have not been saved.',
    });
