  function openUserSafetyReport(user, { parentModal = null, onBlocked = null } = {}) {
    const userId = Number(user?.id);
    if (!Number.isSafeInteger(userId) || userId < 1) return null;
    const launch = () => {
      const firstName = String(user.display_name || 'this player').split(' ')[0];
      const sheet = openModal(`
        ${modalHead(`Report ${firstName}`, 'alert-triangle')}
        <p class="row-sub profile-report-intro">What’s going on? Reports are private and go to the Third Shot safety team.</p>
        <form id="profile-report-form" novalidate>
          <fieldset class="profile-report-choices">
            <legend class="sr-only">Reason for reporting ${esc(user.display_name || 'this player')}</legend>
            ${['Harassment or abusive messages', 'Fake or manipulated scores', 'Spam or fake account', 'Something else']
              .map((reason) => `<label class="choice-card profile-report-choice"><input type="radio" name="profile-report-reason" value="${esc(reason)}" /><span><b>${esc(reason)}</b></span></label>`).join('')}
          </fieldset>
          <div class="form-field profile-report-details">
            <label for="profile-report-details">Details <span class="field-optional">Optional</span></label>
            <textarea id="profile-report-details" rows="4" maxlength="2000" placeholder="Share context that will help us review this safely."></textarea>
            <small class="field-help"><span id="profile-report-count">0</span>/2,000 characters</small>
          </div>
          <label class="card row profile-report-block-choice">
            <input type="checkbox" id="profile-report-block" />
            <span class="row-main"><span class="row-title">Also block ${esc(firstName)}</span><span class="row-sub">Hide each other from search, nearby players, and messages.</span></span>
          </label>
          <p class="form-error inline-action-error" data-inline-action-error role="alert" tabindex="-1" hidden></p>
          <button type="submit" class="btn btn-primary btn-block" id="profile-report-submit">Send report</button>
        </form>
      `, { label: `Report ${user.display_name || 'player'}` });
      const formUX = bindModalFormUX(sheet, '#profile-report-submit');
      const details = sheet.querySelector('#profile-report-details');
      details.addEventListener('input', () => {
        sheet.querySelector('#profile-report-count').textContent = details.value.length.toLocaleString();
      });
      const discardGuard = bindModalDiscardConfirmation(sheet, {
        isDirty: formUX.isDirty,
        title: 'Discard this report?',
        message: 'Your report has not been sent yet.',
      });
      sheet.querySelector('#profile-report-form').addEventListener('submit', async (event) => {
        event.preventDefault();
        clearInlineActionError(sheet);
        const selected = sheet.querySelector('input[name="profile-report-reason"]:checked');
        if (!selected) {
          formUX.showError('Choose the reason that best fits.', sheet.querySelector('input[name="profile-report-reason"]'));
          return;
        }
        const submit = sheet.querySelector('#profile-report-submit');
        const reportControls = [...sheet.querySelectorAll(
          'input[name="profile-report-reason"], #profile-report-details, #profile-report-block',
        )];
        const resetAction = beginButtonAction(submit, 'Sending report…', reportControls);
        if (!resetAction) return;
        const blockToo = sheet.querySelector('#profile-report-block').checked;
        try {
          await api(`/users/${userId}/report`, {
            method: 'POST',
            body: JSON.stringify({
              reason: selected.value,
              details: details.value.trim(),
            }),
          });
          let blocked = false;
          if (blockToo && !user.is_blocked) {
            try {
              await api(`/users/${userId}/block`, { method: 'POST' });
              blocked = true;
              user.is_blocked = true;
              state.chatFriendsCache = null;
              onBlocked?.();
            } catch { /* the safety report remains submitted */ }
          }
          discardGuard.authorizeClose();
          const reportBox = sheet.querySelector('.modal');
          reportBox.innerHTML = `
            ${modalHead('Report sent', 'check-circle')}
            <div class="settings-empty-state profile-report-success" role="status">
              <span aria-hidden="true">${uiIcon('check-circle')}</span>
              <b>Thanks for helping keep Third Shot safe</b>
              <span>We received your private report.${blockToo ? (blocked ? ` ${esc(firstName)} is also blocked.` : ' The report was sent, but blocking did not finish; you can try again from their profile.') : ''}</span>
            </div>
            <button type="button" class="btn btn-primary btn-block modal-close">Done</button>`;
          setDialogLabel(reportBox, 'Report sent');
          reportBox.querySelector('.modal-close')?.focus({ preventScroll: true });
        } catch (error) {
          resetAction();
          showInlineActionError(sheet, error.message);
        }
      });
      return sheet;
    };
    return parentModal ? openChildModal(parentModal, launch) : launch();
  }

  function chatBodyHtml(rawBody) {
    const body = String(rawBody || '');
    const tokenPattern = /(https?:\/\/[^\s<>]+|(?:\+?\d[\d(). -]{6,}\d))/gi;
    let html = '';
    let cursor = 0;
    for (const match of body.matchAll(tokenPattern)) {
      html += esc(body.slice(cursor, match.index));
      const token = match[0];
      if (/^https?:\/\//i.test(token)) {
        const clean = token.replace(/[),.!?;:]+$/, '');
        const trailing = token.slice(clean.length);
        html += `<a class="chat-link" href="${esc(clean)}" target="_blank" rel="noopener noreferrer">${esc(clean)}</a>${esc(trailing)}`;
      } else {
        const digits = token.replace(/\D/g, '');
        html += digits.length >= 7 && digits.length <= 15
          ? `<a class="chat-link" href="tel:${digits}">${esc(token)}</a>`
          : esc(token);
      }
      cursor = match.index + token.length;
    }
    html += esc(body.slice(cursor));
    return html.replace(/\r?\n/g, '<br>');
  }

  function setupChat() {
    configureCommunityLaneTabs();
    $('#chat-compose')?.addEventListener('click', openNewMessageSheet);
    $('#chat-segments').addEventListener('click', (e) => {
      const btn = e.target.closest('button');
      if (!btn) return;
      const changed = state.chatSeg !== btn.dataset.seg;
      state.chatSeg = btn.dataset.seg;
      document.querySelectorAll('#chat-segments button').forEach((b) => {
        const active = b === btn;
        b.classList.toggle('active', active);
        b.setAttribute('aria-selected', String(active));
      });
      renderChat({ reuseFresh: !changed });
    });
  }

  function openNewMessageSheet() {
    const modal = openModal(`
      ${modalHead('New message')}
      <div class="form-field community-compose-search">
        <label for="new-message-search">Find a player</label>
        <input type="search" id="new-message-search" placeholder="Name or exact email" autocomplete="off" aria-controls="new-message-results" />
        <small class="field-help">Search by display name, or enter someone’s full email address.</small>
      </div>
      <div id="new-message-results" class="community-compose-results" aria-live="polite">
        <div class="settings-empty-state"><span aria-hidden="true">${uiIcon('message')}</span><p>Choose someone to start a conversation.</p></div>
      </div>
    `, { label: 'New message' });
    const input = modal.querySelector('#new-message-search');
    const results = modal.querySelector('#new-message-results');
    let timer = null;
    let searchSeq = 0;

    const bindResults = () => {
      results.querySelectorAll('[data-compose-user]').forEach((button) => {
        button.addEventListener('click', () => {
          const userId = Number(button.dataset.composeUser);
          if (Number.isSafeInteger(userId) && userId > 0) {
            transitionModal(modal, () => openThread(userId));
          }
        });
      });
    };
    const runSearch = async (query) => {
      const seq = ++searchSeq;
      results.setAttribute('aria-busy', 'true');
      results.innerHTML = `<div class="player-search-status" role="status">${uiIcon('search')} Looking for players…</div>`;
      try {
        const data = await api(`/users/search?q=${encodeURIComponent(query)}`);
        if (seq !== searchSeq || !modal.isConnected || input.value.trim() !== query) return;
        const items = Array.isArray(data.items) ? data.items : [];
        results.innerHTML = items.length ? items.map((user) => {
          return `<button type="button" class="card row nav-row-button community-compose-result" data-compose-user="${user.id}" aria-label="Message ${esc(user.display_name)}">
            ${avatarHtml(user, 'sm', 'span')}
            <span class="row-main"><span class="row-title">${esc(user.display_name)}</span><span class="row-sub">${playerSkillIdentityHtml(user)}</span></span>
            ${uiIcon('chevron-right', 'chev')}
          </button>`;
        }).join('') : `<div class="settings-empty-state"><span aria-hidden="true">${uiIcon('search')}</span><p>No players found for “${esc(query)}”.</p></div>`;
        bindResults();
      } catch (error) {
        if (seq !== searchSeq || !modal.isConnected || input.value.trim() !== query) return;
        renderError(results, error.message, () => runSearch(input.value.trim()));
      } finally {
        if (seq === searchSeq) results.removeAttribute('aria-busy');
      }
    };
    input.addEventListener('input', () => {
      clearTimeout(timer);
      searchSeq += 1;
      const query = input.value.trim();
      if (query.length < 2) {
        results.removeAttribute('aria-busy');
        results.innerHTML = query
          ? '<div class="settings-empty-state"><p>Type at least two characters.</p></div>'
          : `<div class="settings-empty-state"><span aria-hidden="true">${uiIcon('message')}</span><p>Choose someone to start a conversation.</p></div>`;
        return;
      }
      timer = setTimeout(() => runSearch(query), 300);
    });
    modal._cleanupFns?.push(() => {
      clearTimeout(timer);
      searchSeq += 1;
    });
    queueMicrotask(() => input.focus({ preventScroll: true }));
    return modal;
  }

  function inboxMessagePreviewText(item) {
    const message = item.lastMessage;
    if (!message) return item.emptyText || 'Start the conversation';
    if (message.open_call) {
      const call = message.open_call;
      if (call.state === 'open') return `${call.spots_left} spot${call.spots_left === 1 ? '' : 's'} left · ${fmtDateTime(call.scheduled_at)}`;
      if (call.state === 'full') return `Roster full · ${fmtDateTime(call.scheduled_at)}`;
      return call.state === 'withdrawn' ? 'Court game post withdrawn' : 'Court game post closed';
    }
    const body = message.body ? message.body.slice(0, 72)
      : message.has_image ? 'Photo' : 'New message';
    if (message.sender_id === state.me.id) return `You: ${body}`;
    if (item.kind === 'dm') return body;
    const sender = (message.sender_name || 'Player').split(' ')[0];
    return `${sender}: ${body}`;
  }

  function inboxMessagePreview(item) {
    return esc(inboxMessagePreviewText(item));
  }

  function competitionInboxContext(room) {
    const label = {
      registration: 'Open for signups', active: 'In progress', upcoming: 'Upcoming',
      awaiting_confirmation: 'Score awaiting confirmation', completed: 'Completed',
    }[room.status] || 'Competition chat';
    const details = [label];
    if (room.event_at) details.push(fmtDateTime(room.event_at));
    if (room.court_name && !room.title.includes(room.court_name)) details.push(room.court_name);
    return details.join(' · ');
  }

  function universalInboxHtml(
    data, rooms, clubs, competitions, crews = { items: [], invitations: [] },
    { filter = 'all', groupPage = false } = {},
  ) {
    const items = [];
    (data.items || []).forEach((chat) => items.push({
      kind: 'dm', id: chat.user.id, title: chat.user.display_name,
      iconHtml: avatarHtml(chat.user, '', 'span'), lastMessage: chat.last_message,
      unread: chat.unread || 0, emptyText: 'Send a message',
      messageRequest: chat.message_request === true,
    }));
    (clubs.items || []).forEach((club) => items.push({
      kind: 'club', id: club.id, title: club.name,
      iconHtml: `<span class="inbox-room-icon">${uiIcon('building')}</span>`, lastMessage: club.last_message,
      unread: club.unread || 0,
      emptyText: club.announcement ? `Announcement: ${club.announcement.slice(0, 72)}`
        : `${club.member_count} member${club.member_count === 1 ? '' : 's'}${club.home_court_name ? ` · ${club.home_court_name}` : ''}`,
    }));
    (crews.items || []).forEach((value) => {
      const crew = crewSummaryFrom(value);
      if (!crew) return;
      items.push({
        kind: 'crew', id: crew.id, title: crew.name,
        iconHtml: `<span class="inbox-room-icon crew">${uiIcon('users')}</span>`,
        lastMessage: value.last_message || crew.last_message || null,
        unread: Number(value.unread ?? crew.unread) || 0,
        emptyText: `${crew.member_count} player${crew.member_count === 1 ? '' : 's'}${crew.pending_count ? ` · ${crew.pending_count} invited` : ''}${crew.default_court_name ? ` · ${crew.default_court_name}` : ''}`,
      });
    });
    (rooms.items || []).forEach((room) => items.push({
      kind: 'court', id: room.court.id, title: room.court.name,
      iconHtml: `<span class="inbox-room-icon">${uiIcon('pickleball')}</span>`, lastMessage: room.last_message,
      unread: room.unread || 0, emptyText: 'Court chat',
    }));
    (competitions.items || []).forEach((room) => items.push({
      kind: room.kind, id: room.id, title: room.title,
      iconHtml: `<span class="inbox-room-icon">${uiIcon(room.kind === 'game' ? 'pickleball' : room.kind === 'tournament' ? 'trophy' : 'target')}</span>`,
      lastMessage: room.last_message, unread: room.unread || 0,
      emptyText: competitionInboxContext(room), eventAt: room.event_at, status: room.status,
    }));

    const filterKinds = {
      all: null,
      direct: new Set(['dm']),
      games: new Set(['game', 'tournament', 'league']),
      groups: new Set(['club', 'crew']),
      courts: new Set(['court']),
    };
    const selectedFilter = Object.hasOwn(filterKinds, filter) ? filter : 'all';
    const selectedKinds = filterKinds[selectedFilter];
    const activeStatuses = new Set(['registration', 'active', 'upcoming', 'awaiting_confirmation']);
    const visibleItems = items.filter((item) => (
      (!selectedKinds || selectedKinds.has(item.kind))
      // Upcoming sessions remain reachable from their game screen. Only
      // create an inbox row once that room contains an actual conversation
      // (or unread activity), instead of crowding out people's messages.
      && (item.kind !== 'game'
        || item.unread > 0
        || (activeStatuses.has(item.status) && item.lastMessage))
    ));
    const recent = visibleItems.filter((item) => item.lastMessage)
      .sort((a, b) => b.lastMessage.id - a.lastMessage.id);
    const ready = visibleItems.filter((item) => !item.lastMessage)
      .sort((a, b) => {
        if (a.eventAt && b.eventAt) return new Date(a.eventAt) - new Date(b.eventAt);
        return a.eventAt ? -1 : b.eventAt ? 1 : a.title.localeCompare(b.title);
      });
    const kindLabel = { dm: 'Direct', club: 'Community', crew: 'Private group', court: 'Court', game: 'Game', tournament: 'Tournament', league: 'League' };
    const rowHtml = (item, extraClass = '') => {
      const attention = item.unread
        ? `, ${item.unread} unread message${item.unread === 1 ? '' : 's'}` : '';
      const preview = inboxMessagePreviewText(item);
      const when = item.lastMessage ? `, ${fmtInboxTimestamp(item.lastMessage.created_at)}` : '';
      return `
      <button type="button" class="card row inbox-row ${extraClass}" data-inbox-kind="${item.kind}" data-inbox-id="${item.id}" data-inbox-title="${esc(item.title)}" data-unread="${item.unread}" aria-label="${esc(`${item.title}, ${kindLabel[item.kind]} chat${attention}, ${preview}${when}`)}">
        ${item.iconHtml}
        <span class="row-main">
          <span class="row-title" style="display:block">${esc(item.title)}<span class="inbox-kind">${item.messageRequest ? 'Message request' : kindLabel[item.kind]}</span></span>
          <span class="row-sub" style="display:block">${inboxMessagePreview(item)}</span>
        </span>
        ${item.unread ? `<span class="badge" style="position:static">${item.unread > 99 ? '99+' : item.unread}</span>`
          : item.lastMessage ? `<span class="row-sub inbox-time">${fmtInboxTimestamp(item.lastMessage.created_at)}</span>` : uiIcon('chevron-right', 'chev')}
      </button>`;
    };

    const invitations = pendingCrewInvitationEntries(crews);
    const filterLabels = [
      ['all', 'All'], ['direct', 'Direct'], ['games', 'Games'],
      ['courts', 'Courts'],
    ];
    let html = groupPage ? '' : `<div class="chat-kind-filters" role="group" aria-label="Filter chats">
      ${filterLabels.map(([value, label]) => `<button type="button" data-chat-filter="${value}" class="${selectedFilter === value ? 'active' : ''}" aria-pressed="${selectedFilter === value}">${label}</button>`).join('')}
    </div>`;
    const unreadConversationCount = items.reduce(
      (total, item) => total + (Number(item.unread) || 0), 0,
    );
    if (selectedFilter === 'all' && unreadConversationCount) {
      html += `<div class="chat-list-tools"><span>${unreadConversationCount} unread message${unreadConversationCount === 1 ? '' : 's'}</span><button type="button" class="btn btn-link" id="chats-mark-all-read">Mark all read</button></div>`;
    }
    if ((selectedFilter === 'all' || selectedFilter === 'groups') && invitations.length) {
      html += '<div class="section-label" style="margin-top:4px">Play group invitations</div>';
      html += invitations.map(({ invitation, crew }) => {
        const inviter = invitation.inviter && invitation.inviter.display_name
          ? invitation.inviter.display_name
          : invitation.invited_by_name || invitation.creator_name || 'A player';
        const playedAt = invitation.source_court_name || crew.default_court_name;
        return `<div class="card crew-invite-card" data-crew-invitation="${crew.id}">
          <button type="button" class="row crew-invite-main" data-crew-preview="${crew.id}" aria-label="Preview invitation to ${esc(crew.name)}">
            ${invitation.inviter ? avatarHtml(invitation.inviter, 'sm', 'span') : `<span class="inbox-room-icon crew" aria-hidden="true">${uiIcon('users')}</span>`}
            <span class="row-main"><span class="row-title">${esc(crew.name)}</span><span class="row-sub">${esc(inviter)} invited you${playedAt ? ` · You played together at ${esc(playedAt)}` : ''}</span></span>
            ${uiIcon('chevron-right', 'chev')}
          </button>
          <div class="crew-invite-actions">
            <button type="button" class="btn btn-secondary" data-crew-response="decline" data-crew-id="${crew.id}">${uiIcon('x')} Decline</button>
            <button type="button" class="btn btn-primary" data-crew-response="accept" data-crew-id="${crew.id}">${uiIcon('check-circle')} Join group</button>
          </div>
        </div>`;
      }).join('');
    }
    if (selectedFilter === 'groups') {
      const crewItems = visibleItems.filter((item) => item.kind === 'crew');
      const clubItems = visibleItems.filter((item) => item.kind === 'club');
      // Related court and competition conversations are deliberately drawn
      // from the unfiltered inbox. `visibleItems` contains only club/crew rows
      // while the Groups filter is active, which made this section unreachable.
      const conversationItems = items.filter((item) => (
        ['court', 'tournament', 'league'].includes(item.kind)
        && (item.unread > 0 || item.lastMessage || activeStatuses.has(item.status))
      ))
        .sort((a, b) => {
          if (a.unread !== b.unread) return b.unread - a.unread;
          if (a.lastMessage && b.lastMessage) return b.lastMessage.id - a.lastMessage.id;
          return a.lastMessage ? -1 : b.lastMessage ? 1 : a.title.localeCompare(b.title);
        });
      html += `<div class="community-discovery-hero">
        <span class="row-main"><b>Find or create a group</b><small>Join a public community group, or create a private group for people you play with.</small></span>
        <div class="community-group-actions">
          <button class="btn btn-primary" id="club-find">${uiIcon('search')} Find public groups</button>
          <button class="btn btn-secondary" id="group-new">${uiIcon('plus')} Create a group</button>
        </div>
      </div>`;
      if (crewItems.length) {
        html += '<div class="section-label" style="margin-top:4px">Private groups</div>';
        html += crewItems.map((item) => rowHtml(item)).join('');
      }
      if (clubItems.length) {
        html += '<div class="section-label">Your community groups</div>';
        html += clubItems.map((item) => rowHtml(item)).join('');
      }
      if (!crewItems.length && !clubItems.length && !invitations.length) {
        html += '<div class="empty-state community-lane-empty">Your groups will appear here. Find local players or bring your friends together.</div>';
      }
      if (!groupPage && conversationItems.length) {
        html += '<div class="section-label">Related conversations</div>';
        html += conversationItems.map((item) => rowHtml(item)).join('');
      }
      return html;
    }

    if (recent.length) {
      html += '<div class="section-label" style="margin-top:4px">Recent chats</div>';
      html += recent.map((item) => rowHtml(item)).join('');
    }
    if (ready.length) {
      html += `<div class="section-label" style="margin-top:${recent.length ? '18px' : '4px'}">Everything else</div>`;
      html += ready.map((item, index) => rowHtml(item, index >= 8 ? 'inbox-ready-extra hidden' : '')).join('');
      if (ready.length > 8) {
        html += `<button type="button" class="btn btn-secondary btn-block" id="inbox-show-ready">Show ${ready.length - 8} more chats</button>`;
      }
    }
    if (!visibleItems.length) {
      html += `<div class="empty-state"><span class="empty-state-icon" aria-hidden="true">${uiIcon('message')}</span><b>No ${selectedFilter === 'all' ? '' : `${filterLabels.find(([value]) => value === selectedFilter)?.[1].toLowerCase()} `}chats yet.</b><span class="empty-state-copy">Start with a player or coordinate an upcoming play session.</span>
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:14px">
          <button class="btn btn-secondary" data-goto="chat-friends">Find players</button>
          <button class="btn btn-primary" data-goto="new-game">Plan a play session</button>
        </div></div>`;
    }
    return html;
  }

  function bindCommunityConversationRows(el) {
    el.querySelectorAll('[data-inbox-kind]').forEach((row) => row.addEventListener('click', async () => {
      if (row.disabled) return;
      row.disabled = true;
      const kind = row.dataset.inboxKind;
      const id = Number(row.dataset.inboxId);
      let roomModal = null;
      try {
        if (kind === 'dm') roomModal = await openThread(id);
        else if (kind === 'court') roomModal = await openCourtChat({ id, name: row.dataset.inboxTitle });
        else if (kind === 'club') roomModal = await openClubScreen(id, { destination: 'chat' });
        else if (kind === 'crew') roomModal = await openCrewChatById(id);
        else if (kind === 'game') roomModal = await openGameChat({ id });
        else if (kind === 'tournament') roomModal = await openTournamentChat({ id });
        else if (kind === 'league') roomModal = await openLeagueChat({ id, name: row.dataset.inboxTitle });
      } catch (error) {
        if (!error?.isCancelled && !error?.isStaleSession) errorToast(error);
      } finally {
        row.disabled = false;
      }
      if (!roomModal?._cleanupFns || roomModal._destroyed) return;
      let refreshedAfterClose = false;
      roomModal._cleanupFns.push(() => {
        if (refreshedAfterClose) return;
        refreshedAfterClose = true;
        // Opening the room already performed the authoritative read. Refresh
        // the inbox once the player returns, rather than multiplying /inbox
        // traffic underneath the still-open conversation.
        queueMicrotask(() => {
          if (state.tab === 'chat' && ['chats', 'groups'].includes(state.chatSeg)) renderChat();
        });
      });
    }));
  }

