  function bindCommunityPartialRetry(el) {
    el.querySelector('[data-community-feed-retry]')?.addEventListener('click', (event) => {
      event.currentTarget.disabled = true;
      renderChat();
    });
  }

  async function renderChat({ reuseFresh = false, useCachedData = false } = {}) {
    const seg = state.chatSeg;
    const liveEl = $('#chat-content');
    liveEl.setAttribute('aria-labelledby', `chat-tab-${seg}`);
    const peopleKey = seg === 'friends' ? `:${state.peopleMode}` : '';
    const viewKey = `${state.me?.id || 'signed-out'}:chat:${seg}${peopleKey}:${areaViewKey()}`;
    if (reuseFresh && viewIsFresh(liveEl, viewKey)) return;
    const renderSeq = ++state.chatRenderSeq;
    const hadUsableContent = beginViewRender(liveEl, viewKey, 5);
    const el = document.createElement('div');
    const commit = () => {
      if (renderSeq !== state.chatRenderSeq || state.chatSeg !== seg) return false;
      commitViewRender(liveEl, el, viewKey);
      return true;
    };
    try {
      if (seg === 'chats' || seg === 'groups') {
        const inbox = await api('/inbox');
        const data = inbox.direct || { items: [] };
        const rooms = inbox.courts || { items: [] };
        const clubs = inbox.clubs || { items: [] };
        const competitions = inbox.competitions || { items: [] };
        const crews = inbox.crews || { items: [], invitations: [] };
        if (renderSeq !== state.chatRenderSeq || state.chatSeg !== seg) return;
        syncPendingCrewInvitesFromMine(crews);
        syncCommunityUnreadLanes(rooms, clubs, competitions, crews);
        renderBadges();
        const failedLabels = Object.keys(inbox.errors || {}).map((key) => ({
          direct: 'Direct messages', courts: 'Court chats', clubs: 'Community groups',
          competitions: 'Game chats', crews: 'Private groups',
        }[key] || key));
        el.innerHTML = communityPartialLoadHtml(failedLabels)
          + universalInboxHtml(data, rooms, clubs, competitions, crews, {
            filter: seg === 'groups' ? 'groups' : (state.chatConversationFilter === 'groups' ? 'all' : state.chatConversationFilter),
            groupPage: seg === 'groups',
          });
        bindCommunityPartialRetry(el);
        bindCommunityConversationRows(el);
        bindCrewInvitationActions(el);
        el.querySelectorAll('[data-chat-filter]').forEach((button) => button.addEventListener('click', () => {
          const next = button.dataset.chatFilter;
          if (next === state.chatConversationFilter) return;
          state.chatConversationFilter = next;
          renderChat();
        }));
        el.querySelector('#inbox-show-ready')?.addEventListener('click', (event) => {
          const firstRevealed = el.querySelector('.inbox-ready-extra');
          el.querySelectorAll('.inbox-ready-extra').forEach((row) => row.classList.remove('hidden'));
          event.currentTarget.remove();
          firstRevealed?.focus({ preventScroll: true });
        });
        el.querySelector('#chats-mark-all-read')?.addEventListener('click', async (event) => {
          const button = event.currentTarget;
          const reset = beginButtonAction(button, 'Marking…');
          if (!reset) return;
          try {
            await api('/chat/read-all', { method: 'POST', body: '{}' });
            state.unreadMessages = 0;
            state.communityRoomUnread = 0;
            state.communityMessageUnread = 0;
            state.communityGroupUnread = 0;
            renderBadges();
            renderChat();
            toast('All chats marked read');
          } catch (error) {
            reset();
            toast(error.message);
          }
        });
        el.querySelector('#crew-new')?.addEventListener('click', openCreatePlayGroupSheet);
        el.querySelector('#group-new')?.addEventListener('click', openCreateGroupChoiceSheet);
        el.querySelector('#club-find')?.addEventListener('click', openFindClubsSheet);
        el.querySelector('#club-new')?.addEventListener('click', openCreateClubSheet);
      } else {
        await renderPeopleLane(el, { useCachedData });
      }
      commit();
    } catch (e) {
      if (renderSeq !== state.chatRenderSeq || state.chatSeg !== seg) return;
      if (hadUsableContent) {
        retainViewAfterError(liveEl, `${e.message} Showing your last update.`, () => renderChat());
      } else {
        renderError(el, e.message, () => renderChat());
        commit();
      }
    }
  }

  function nearbyPlayerLocationHtml(player) {
    if (player.checked_in_court) {
      return `${uiIcon('map-pin', 'community-inline-icon')} At ${esc(player.checked_in_court.name)}${player.checked_in_court.looking_for_game
        ? ' · <b style="color:var(--green-accent)">wants to play!</b>' : ''}`;
    }
    const selfRating = Number(player.skill_rating);
    const profile = Number.isFinite(selfRating)
      ? `${selfRating.toFixed(1)} self-rating`
      : 'Self-rating not set';
    const distance = Number(player.distance_miles);
    const distanceText = Number.isFinite(distance) ? ` · ${distance} mi from your area` : '';
    const seenAt = new Date(player.last_seen_at || '').getTime();
    if (player.location_source === 'recent' && Number.isFinite(seenAt)) {
      const minutes = Math.max(0, Math.floor((Date.now() - seenAt) / 60000));
      const when = minutes < 1 ? 'just now' : `${fmtDuration(minutes)} ago`;
      return `${profile} · Last seen ${when}${distanceText ? distanceText.replace('your area', 'this area then') : ''}`;
    }
    if (player.location_source === 'home_court' && player.home_court_name) {
      return `${profile} · Plays at ${esc(player.home_court_name)}${distanceText}`;
    }
    if (player.location_source === 'home_area') {
      return `${profile} · Profile area${distanceText}`;
    }
    return `${profile} · Nearby from their profile${distanceText}`;
  }

  async function renderNearbyPlayers(el) {
    const loc = committedAreaLatLng();
    if (!loc) {
      el.innerHTML = `<section class="play-area-setup community-area-setup" role="status">
        <span class="play-area-setup-icon" aria-hidden="true">${uiIcon('map-pin')}</span>
        <span class="row-main"><b>Set your area to find nearby players</b><small>Choose a city or use your location. Third Shot will not infer an area from the court map.</small></span>
        <button type="button" class="btn btn-primary" data-set-community-area>Set area</button>
      </section>`;
      el.querySelector('[data-set-community-area]')?.addEventListener('click', () => {
        openHomeAreaOnboarding({ replay: true, onComplete: () => renderChat() });
      });
      return;
    }
    const skill = state.nearbySkill || '';
    let data;
    let looking;
    try {
      [data, looking] = await Promise.all([
        api(`/players/nearby?lat=${loc.lat}&lng=${loc.lng}&radius=50${skill ? `&level=${encodeURIComponent(skill)}` : ''}`),
        api(`/players/looking?lat=${loc.lat}&lng=${loc.lng}&radius=50`).catch(() => null),
      ]);
    } catch (e) {
      renderError(el, e.message, () => renderNearbyPlayers(el));
      return;
    }

    const skills = [['', 'All'], ['3.0', '3.0'], ['3.5', '3.5'], ['4.0', '4.0+']];
    const matchesLevel = (person) => {
      if (!skill) return true;
      const rating = Number(person?.skill_rating ?? person?.self_rating);
      if (!Number.isFinite(rating)) return false;
      if (skill === '3.0') return rating >= 3 && rating < 3.5;
      if (skill === '3.5') return rating >= 3.5 && rating < 4;
      return skill === '4.0' && rating >= 4;
    };
    const rallies = normalizeLookingRallies(looking);
    const pulses = normalizeLookingPulses(looking).filter((pulse) => matchesLevel(pulse.user));
    const pulsesById = new Map(pulses.map((pulse) => [pulse.id, pulse]));
    const players = [...(Array.isArray(data.items) ? data.items : [])].sort((a, b) => {
      const rank = (player) => {
        const playerRally = playerRallySummary(player);
        if (playerRally && playerRally.gameId) return 4;
        if (player.checked_in_court && player.checked_in_court.looking_for_game) return 3;
        if (player.checked_in_court) return 2;
        return player.active_now ? 1 : 0;
      };
      return rank(b) - rank(a)
        || Number(a.distance_miles ?? Infinity) - Number(b.distance_miles ?? Infinity)
        || String(a.display_name || '').localeCompare(String(b.display_name || ''));
    });
    let html = `
      <div class="nearby-level-filters" role="group" aria-label="Filter nearby players by level">
        ${skills.map(([value, label]) => `<button type="button" data-nearby-level="${value}" class="${value === skill ? 'active' : ''}" aria-pressed="${value === skill}">${label}</button>`).join('')}
      </div>`;

    if (pulses.length) {
      html += `<div class="section-label section-label-icon">${uiIcon('bell')} Can play this hour</div><div class="nearby-play-pulses">`;
      html += pulses.map((pulse) => {
        const person = pulse.user || {};
        const first = String(person.display_name || 'A nearby player').split(/\s+/)[0];
        const proximity = pulse.distanceMiles == null ? '' : `${pulse.distanceMiles} mi from your area`;
        return `
          <div class="card play-pulse-nearby-card">
            ${safePositiveId(person.id)
              ? `<button type="button" class="play-pulse-nearby-person" data-view-user="${safePositiveId(person.id)}" aria-label="View ${esc(person.display_name || 'nearby player')}'s profile">${avatarHtml(person, 'sm', 'span')}</button>`
              : `<span class="play-pulse-nearby-person" aria-hidden="true"><span class="play-pulse-avatar">${uiIcon('pickleball')}</span></span>`}
            <div class="play-pulse-nearby-copy">
              <b>${esc(first)} wants to play at ${esc(pulse.courtName)} until ${esc(fmtTimeShort(pulse.expiresAt))}</b>
              ${proximity ? `<span>${esc(proximity)}</span>` : ''}
              <small>Join them for a casual game.</small>
            </div>
            <button type="button" class="btn btn-primary btn-sm" data-play-pulse-accept="${pulse.id}" aria-label="Join ${esc(first)} at ${esc(pulse.courtName)}" title="We’ll set up a casual game and let ${esc(first)} know">I’m in</button>
          </div>`;
      }).join('');
      html += '</div>';
    }

    if (rallies.length) {
      html += '<div class="section-label">Casual sessions starting now</div><div class="nearby-rallies">';
      html += rallies.map((rally) => {
        const action = rallyActionState(rally);
        return `
          <div class="card nearby-rally-card">
            <div class="nearby-rally-copy"><b>${esc(rally.courtName)}</b><span>${esc(rallyCountsText(rally))}</span></div>
            ${action.enabled
              ? `<button type="button" class="btn btn-primary btn-sm" data-rally-action="${action.kind}" ${rallyDatasetAttributes(rally)}>${esc(action.label)}</button>`
              : `<span class="tag warn nearby-rally-unavailable">${esc(action.label)}</span>`}
          </div>`;
      }).join('');
      html += '</div>';
    }

    html += players.length
      ? players.map((p) => {
          const playerRally = playerRallySummary(p);
          const readyAtCourt = !!(p.checked_in_court && p.checked_in_court.looking_for_game);
          let action = '';
          if (playerRally && playerRally.gameId) {
            const rallyAction = rallyActionState(playerRally);
            action = rallyAction.enabled
              ? `<button type="button" class="btn btn-primary btn-sm" data-rally-action="${rallyAction.kind}" ${rallyDatasetAttributes(playerRally)}>${esc(rallyAction.label)}</button>`
              : `<span class="tag warn" style="margin:0">${esc(rallyAction.label)}</span>`;
          } else if (readyAtCourt) {
            action = `<button type="button" class="btn btn-secondary btn-sm" data-nearby-court="${p.checked_in_court.id}">${uiIcon('map-pin')} View court</button>`;
          } else if (p.is_friend) {
            action = '';
          } else if (p.friendship_status === 'pending') action = p.outgoing
            ? '<span class="tag" style="margin:0">Pending</span>'
            : `<button class="btn btn-primary btn-sm" data-respond-inline="${p.friendship_id}">${uiIcon('check-circle')} Accept</button>`;
          else action = `<button class="btn btn-primary btn-sm" data-add-friend="${p.id}">${uiIcon('plus')} Add</button>`;
          action = `<div class="nearby-player-actions">
            ${p.can_message ? `<button type="button" class="btn btn-secondary btn-sm" data-msg="${p.id}">${uiIcon('message')} Message</button>` : ''}
            ${action}
          </div>`;
          let sub = nearbyPlayerLocationHtml(p);
          if (availabilityOverlap(state.me.availability, p.availability)) {
            sub += ` · <b class="community-inline-status">${uiIcon('clock', 'community-inline-icon')} Plays your times</b>`;
          }
          return `
            <div class="card row nearby-player${readyAtCourt || playerRally ? ' is-ready' : ''}" data-relationship-row>
              <button type="button" class="player-profile-link" data-view-user="${p.id}" aria-label="View ${esc(p.display_name)}'s profile">
                ${avatarHtml(p)}
                <span class="row-main">
                  <span class="row-title">${esc(p.display_name)}${p.current_streak >= 2 ? ` ${uiIcon('zap', 'community-streak-icon')}` : ''}</span>
                  <span class="row-sub">${sub}</span>
                  ${p.active_now ? '<span class="community-active-chip"><span class="community-presence-dot" aria-hidden="true"></span>Recently active in Third Shot</span>' : ''}
                </span>
              </button>
              ${action}
            </div>`;
        }).join('')
      : pulses.length || rallies.length ? ''
        : `<div class="empty-state community-nearby-empty">
            <span class="empty-state-icon" aria-hidden="true">${uiIcon('map-pin')}</span>
            <b>No nearby players yet.</b>
            <span class="empty-state-copy">Check in at a court so others can find you.</span>
            <button type="button" class="btn btn-primary" data-goto="courts">${uiIcon('map')} Browse courts</button>
          </div>`;

    const matchingSkillCount = players.length + pulses.length;
    html += `<div class="empty-state community-nearby-filter-empty" id="nearby-filter-empty" ${!skill || matchingSkillCount ? 'hidden' : ''}>
      <b>No ${esc((skills.find(([value]) => value === skill) || ['', 'nearby'])[1].toLowerCase())} players in this area yet.</b>
      <span class="empty-state-copy">Choose another level or check back after more players join.</span>
    </div>`;

    html += `<details class="nearby-privacy">
      <summary>How location sharing works</summary>
      <p>Court check-ins show where you are now. Free this hour shares only where you intend to play and expires automatically.</p>
    </details>`;

    el.innerHTML = html;
    el.querySelectorAll('[data-nearby-level]').forEach((button) => button.addEventListener('click', () => {
      const selected = button.dataset.nearbyLevel || '';
      if (selected === state.nearbySkill) return;
      state.nearbySkill = selected;
      renderNearbyPlayers(el);
    }));
    el.querySelectorAll('[data-rally-action]').forEach((button) => button.addEventListener('click', () => {
      openReadyRally(rallySummaryFromDataset(button), button);
    }));
    el.querySelectorAll('[data-play-pulse-accept]').forEach((button) => button.addEventListener('click', () => {
      const pulse = pulsesById.get(Number(button.dataset.playPulseAccept));
      if (pulse) openPlayPulseAcceptConfirmation(pulse);
    }));
    el.querySelectorAll('[data-nearby-court]').forEach((button) => button.addEventListener('click', () => {
      openCourtDetail(Number(button.dataset.nearbyCourt));
    }));
    el.querySelectorAll('[data-msg]').forEach((b) => b.addEventListener('click', () => openThread(Number(b.dataset.msg))));
    el.querySelectorAll('[data-add-friend]').forEach((b) => b.addEventListener('click', async () => {
      const row = b.closest('[data-relationship-row]') || b.parentElement;
      clearInlineActionError(row);
      const resetAction = beginButtonAction(b, 'Sending…');
      if (!resetAction) return;
      try {
        await api('/friends/request', { method: 'POST', body: JSON.stringify({ user_id: Number(b.dataset.addFriend) }) });
        toast('Friend request sent!');
        state.chatFriendsCache = null;
        renderChat();
      } catch (e) {
        resetAction();
        showInlineActionError(row, e.message);
      }
    }));
    el.querySelectorAll('[data-respond-inline]').forEach((b) => b.addEventListener('click', async () => {
      const row = b.closest('[data-relationship-row]') || b.parentElement;
      clearInlineActionError(row);
      const resetAction = beginButtonAction(b, 'Accepting…');
      if (!resetAction) return;
      try {
        await api(`/friends/${b.dataset.respondInline}/respond`, { method: 'POST', body: JSON.stringify({ accept: true }) });
        toast('Friend added');
        state.chatFriendsCache = null;
        refreshMe();
        renderChat();
      } catch (e) {
        resetAction();
        showInlineActionError(row, e.message);
      }
    }));
    bindUserButtons(el);
  }

  const pendingFriendDeclines = new Map();

  let disclosureMenuSequence = 0;
  let disclosureMenuDocumentBound = false;
  function bindDisclosureMenus(root = document) {
    root.querySelectorAll('details.friend-row-more, details.thread-more-actions').forEach((details) => {
      if (details.dataset.disclosureMenuBound === '1') return;
      const summary = details.querySelector('summary');
      const menu = details.querySelector('.friend-row-menu, .thread-more-menu');
      if (!summary || !menu) return;
      details.dataset.disclosureMenuBound = '1';
      details.dataset.disclosureMenu = '1';
      if (!menu.id) menu.id = `disclosure-menu-${++disclosureMenuSequence}`;
      summary.setAttribute('aria-haspopup', 'menu');
      summary.setAttribute('aria-controls', menu.id);
      summary.setAttribute('aria-expanded', String(details.open));
      menu.setAttribute('role', 'menu');
      menu.querySelectorAll('button, a[href]').forEach((item) => item.setAttribute('role', 'menuitem'));

      const items = () => [...menu.querySelectorAll('[role="menuitem"]:not([disabled])')];
      const setOpen = (open, { focusSummary = false, focusEdge = 0 } = {}) => {
        details.open = open;
        summary.setAttribute('aria-expanded', String(open));
        if (focusSummary) summary.focus({ preventScroll: true });
        else if (open && focusEdge) {
          const options = items();
          options[focusEdge < 0 ? options.length - 1 : 0]?.focus({ preventScroll: true });
        }
      };
      details.addEventListener('toggle', () => {
        summary.setAttribute('aria-expanded', String(details.open));
        if (details.open) {
          document.querySelectorAll('details[data-disclosure-menu="1"][open]').forEach((other) => {
            if (other !== details) other.open = false;
          });
        }
      });
      details.addEventListener('keydown', (event) => {
        if (event.key === 'Escape' && details.open) {
          event.preventDefault();
          event.stopPropagation();
          setOpen(false, { focusSummary: true });
          return;
        }
        if (event.target === summary && (event.key === 'ArrowDown' || event.key === 'ArrowUp')) {
          event.preventDefault();
          setOpen(true, { focusEdge: event.key === 'ArrowUp' ? -1 : 1 });
          return;
        }
        const options = items();
        const index = options.indexOf(document.activeElement);
        if (index < 0 || !options.length) return;
        let target = null;
        if (event.key === 'ArrowDown') target = options[(index + 1) % options.length];
        else if (event.key === 'ArrowUp') target = options[(index - 1 + options.length) % options.length];
        else if (event.key === 'Home') target = options[0];
        else if (event.key === 'End') target = options[options.length - 1];
        if (target) {
          event.preventDefault();
          target.focus();
        }
      });
      menu.addEventListener('click', (event) => {
        if (event.target.closest('[role="menuitem"]')) setOpen(false);
      });
    });
    if (!disclosureMenuDocumentBound) {
      disclosureMenuDocumentBound = true;
      document.addEventListener('pointerdown', (event) => {
        document.querySelectorAll('details[data-disclosure-menu="1"][open]').forEach((details) => {
          if (!details.contains(event.target)) details.open = false;
        });
      });
    }
  }

  async function renderFriends(el, { useCachedData = false } = {}) {
    let friendBundle = useCachedData && state.chatFriendsCache;
    if (!friendBundle) {
      friendBundle = await Promise.all([
        api('/friends'),
        api('/games/results').catch(() => ({ items: [] })),
        api('/friends/digest').catch(() => null),
        api('/friends/suggestions').catch(() => ({ items: [] })),
      ]);
      state.chatFriendsCache = friendBundle;
    }
    const [data, results, digest, suggestions] = friendBundle;
    let html = `
      <div class="form-field" style="margin-top:4px">
        <label class="sr-only" for="friend-search">Find players by name or email</label>
        <input type="search" id="friend-search" placeholder="Find players by name or email…" autocomplete="off" />
        <div id="friend-search-results" aria-live="polite"></div>
      </div>`;

    const incoming = data.incoming.filter(
      (friend) => !pendingFriendDeclines.has(Number(friend.friendship_id)),
    );
    if (incoming.length) {
      html += '<div class="section-label">Friend requests</div>';
      html += incoming.map((f) => `
        <div class="card row" data-relationship-row>
          ${avatarHtml(f)}
          <div class="row-main">
            <div class="row-title">${esc(f.display_name)}</div>
            <div class="row-sub">${playerSkillIdentityHtml(f)}</div>
          </div>
          <button class="btn btn-primary btn-sm" data-respond="${f.friendship_id}" data-accept="1">Accept</button>
          <button type="button" class="btn btn-secondary btn-sm" data-respond="${f.friendship_id}" data-accept="0" aria-label="Decline friend request from ${esc(f.display_name)}">${uiIcon('x')} Decline</button>
        </div>`).join('');
    }

    // Keep lightweight check-in telemetry out of the primary People view. A
    // weekly recap becomes useful once friends actually played a game, and is
    // grouped with the other optional suggestions below.
    let friendDigestHtml = '';
    if (digest && digest.games) {
      const plural = (n, word) => `${n} ${word}${n === 1 ? '' : 's'}`;
      const bits = [];
      if (digest.games) bits.push(`${plural(digest.games, 'game')} by ${plural(digest.friends_played, 'friend')}`);
      if (digest.checkins) bits.push(plural(digest.checkins, 'court check-in'));
      friendDigestHtml = `<div class="section-label section-label-icon">${uiIcon('activity')} This week among friends</div>
      <div class="card friend-digest-card">
        <div class="row-sub friend-digest-summary">${bits.join(' · ')}</div>
        ${(digest.top || []).map((t) => `
          <button type="button" class="row friend-digest-row" data-view-user="${t.id}" aria-label="View ${esc(t.display_name)}'s profile">
            <span class="nav-row-leading">${uiIcon('users')}</span>
            <span class="row-main">
              <span class="row-title">${esc(t.display_name)}</span>
              <span class="row-sub">${plural(t.games, 'game')}${t.wins + t.losses ? ` · ${t.wins}–${t.losses}` : ''}</span>
            </span>
            ${uiIcon('chevron-right', 'chev')}
          </button>`).join('')}
      </div>`;
    }

    // "Who plays when" — filter friends by their usual-play slots.
    const SLOT_FILTERS = [
      ['', 'All'],
      ['sat-am,sat-pm', 'Sat'],
      ['sun-am,sun-pm', 'Sun'],
      ['mon-eve,tue-eve,wed-eve,thu-eve,fri-eve', 'Weekday eve'],
      ['sat-am,sun-am,mon-am,tue-am,wed-am,thu-am,fri-am', 'Mornings'],
    ];
    const slotFilter = state.friendSlotFilter || '';
    const wantedSlots = slotFilter ? slotFilter.split(',') : null;
    const shownFriends = wantedSlots
      ? data.friends.filter((f) => (f.availability || []).some((s) => wantedSlots.includes(s)))
      : data.friends;

    html += `<div class="section-label">Friends (${data.friends.length})</div>`;
    if (data.friends.length > 1) {
      html += `<div class="quick-times" id="friend-slots" role="group" aria-label="Filter friends by usual play time" style="margin:0 0 10px">${SLOT_FILTERS
        .map(([v, label]) => `<button type="button" data-slots="${v}" class="${v === slotFilter ? 'active' : ''}" aria-pressed="${v === slotFilter}">${label}</button>`).join('')}</div>`;
    }
    if (wantedSlots && !shownFriends.length) {
      html += emptyStateHtml({
        icon: 'clock', title: 'No friends usually play then',
        body: 'Try another time to see everyone again.',
        primary: { id: 'friend-clear-time', label: 'Show all friends', icon: 'refresh' },
      });
    }
    html += shownFriends.length
      ? shownFriends.map((f) => `
          <div class="card row friend-person-row">
            <button type="button" class="player-profile-link" data-view-user="${f.id}" aria-label="View ${esc(f.display_name)}'s profile">
                ${avatarHtml(f)}
                <span class="row-main">
                  <span class="row-title">${esc(f.display_name)}</span>
                  <span class="row-sub">${f.checked_in_court
                  ? `${uiIcon('map-pin', 'community-inline-icon')} At ${esc(f.checked_in_court.name)}${f.checked_in_court.looking_for_game ? ' · <b style="color:var(--green-accent)">wants to play!</b>' : ''}`
                  : playerSkillIdentityHtml(f)}</span>
                </span>
              </button>
              <div class="friend-row-actions">
                <button type="button" class="btn btn-primary btn-sm" data-msg="${f.id}" aria-label="Message ${esc(f.display_name)}">${uiIcon('message')} Message</button>
                <details class="friend-row-more">
                  <summary class="btn btn-secondary btn-sm" aria-label="More actions for ${esc(f.display_name)}" aria-haspopup="menu" aria-expanded="false">${uiIcon('sliders')}<span class="sr-only">More actions</span></summary>
                  <div class="friend-row-menu" role="menu" aria-label="Actions for ${esc(f.display_name)}">
                    ${f.checked_in_court && f.checked_in_court.looking_for_game
                      ? `<button type="button" class="btn btn-secondary btn-block" role="menuitem" data-coming="${f.id}">${uiIcon('pickleball')} I can be there soon</button>` : ''}
                    <button type="button" class="btn btn-secondary btn-block" role="menuitem" data-invite="${f.id}" data-invite-court="${f.checked_in_court ? f.checked_in_court.id : ''}" data-invite-court-name="${f.checked_in_court ? esc(f.checked_in_court.name) : ''}" aria-label="Invite ${esc(f.display_name)} to a game">${uiIcon('send')} Invite to play</button>
                  </div>
                </details>
              </div>
          </div>`).join('')
      : (wantedSlots ? '' : emptyStateHtml({
          icon: 'users', title: 'Build your player circle',
          body: 'Find nearby players or share your invitation link.',
          primary: { goto: 'chat-nearby', label: 'Find nearby players', icon: 'search' },
          secondary: { share: true, label: 'Invite friends', icon: 'send' },
        }));

    let friendSuggestionsHtml = friendDigestHtml;
    // People you've actually played with but haven't friended.
    if (suggestions && suggestions.items && suggestions.items.length) {
      friendSuggestionsHtml += `<div class="section-label">${uiIcon('pickleball')} Players you've played with</div>`;
      friendSuggestionsHtml += suggestions.items.map((s) => `
        <div class="card row" data-relationship-row>
          <button type="button" class="player-profile-link" data-view-user="${s.id}" aria-label="View ${esc(s.display_name)}'s profile">
            ${avatarHtml(s)}
            <span class="row-main">
              <span class="row-title">${esc(s.display_name)}</span>
              <span class="row-sub">${s.games_together} game${s.games_together === 1 ? '' : 's'} together · ${playerSkillIdentityHtml(s)}</span>
            </span>
          </button>
          <div class="friend-suggestion-actions">
            <button type="button" class="btn btn-secondary btn-sm" data-msg="${s.id}">${uiIcon('message')} Message</button>
            <button class="btn btn-primary btn-sm" data-add-friend="${s.id}">${uiIcon('plus')} Add</button>
          </div>
        </div>`).join('');
    }

    // What your friends have been playing — results you weren't part of.
    const friendResults = (results.items || []).filter((g) => g.involves_friend && !g.involves_me).slice(0, 5);
    if (friendResults.length) {
      friendSuggestionsHtml += `<div class="section-label section-label-icon">${uiIcon('trophy')} Friend results</div>`;
      friendSuggestionsHtml += friendResults.map(resultRowHtml).join('');
    }
    if (friendSuggestionsHtml) {
      html += `<details class="friend-suggestions">
        <summary>${uiIcon('lightbulb')} Suggestions and recent play</summary>
        <div class="friend-suggestions-body">${friendSuggestionsHtml}</div>
      </details>`;
    }

    el.innerHTML = html;
    bindDisclosureMenus(el);
    bindGameButtons(el, () => renderChat());

    el.querySelectorAll('[data-respond]').forEach((b) => b.addEventListener('click', async () => {
      const row = b.closest('[data-relationship-row]') || b.parentElement;
      const peers = [...row.querySelectorAll('[data-respond]')];
      clearInlineActionError(row);
      const accepting = b.dataset.accept === '1';
      const resetAction = beginButtonAction(b, accepting ? 'Accepting…' : 'Declining…', peers);
      if (!resetAction) return;
      if (!accepting) {
        const friendshipId = Number(b.dataset.respond);
        const decline = { friendshipId, timer: null };
        pendingFriendDeclines.set(friendshipId, decline);
        row.remove();
        resetAction();
        decline.timer = setTimeout(async () => {
          if (pendingFriendDeclines.get(friendshipId) !== decline) return;
          try {
            await api(`/friends/${friendshipId}/respond`, {
              method: 'POST', body: JSON.stringify({ accept: false }),
            });
            pendingFriendDeclines.delete(friendshipId);
            state.chatFriendsCache = null;
            refreshMe();
          } catch (error) {
            pendingFriendDeclines.delete(friendshipId);
            state.chatFriendsCache = null;
            renderChat();
            toast(error.message || 'The friend request could not be declined.', { tone: 'warning' });
          }
        }, 5250);
        toast('Friend request declined', {
          duration: 5000,
          action: {
            label: 'Undo',
            onClick: () => {
              if (pendingFriendDeclines.get(friendshipId) !== decline) return;
              clearTimeout(decline.timer);
              pendingFriendDeclines.delete(friendshipId);
              renderChat({ useCachedData: true });
            },
          },
        });
        return;
      }
      try {
        await api(`/friends/${b.dataset.respond}/respond`, {
          method: 'POST',
          body: JSON.stringify({ accept: true }),
        });
        toast('Friend added');
        state.chatFriendsCache = null;
        refreshMe();
        renderChat();
      } catch (e) {
        resetAction();
        showInlineActionError(row, e.message);
      }
    }));
    el.querySelector('#friend-slots')?.addEventListener('click', (e) => {
      const btn = e.target.closest('button');
      if (!btn) return;
      state.friendSlotFilter = btn.dataset.slots;
      renderChat({ useCachedData: true });
    });
    el.querySelector('#friend-clear-time')?.addEventListener('click', () => {
      state.friendSlotFilter = '';
      renderChat({ useCachedData: true });
    });
    el.querySelectorAll('[data-invite]').forEach((b) => b.addEventListener('click', () => {
      const court = b.dataset.inviteCourt
        ? { id: Number(b.dataset.inviteCourt), name: b.dataset.inviteCourtName }
        : null;
      openNewGameModal({ court, inviteUserIds: [Number(b.dataset.invite)], visibility: 'private' });
    }));
    el.querySelectorAll('[data-msg]').forEach((b) => b.addEventListener('click', () => {
      openThread(Number(b.dataset.msg));
    }));
    el.querySelectorAll('[data-coming]').forEach((b) => b.addEventListener('click', async () => {
      b.disabled = true;
      try {
        await api(`/players/${b.dataset.coming}/coming`, { method: 'POST' });
        toast('They know you can be there soon');
        b.innerHTML = `${uiIcon('check-circle')} Sent`;
      } catch (e) { toast(e.message); b.disabled = false; }
    }));
    // Suggestion "＋ Add" buttons (search results wire their own separately).
    el.querySelectorAll('.card > [data-add-friend], .card [data-add-friend]:not(#friend-search-results [data-add-friend])').forEach((b) => {
      if (b.closest('#friend-search-results')) return;
      b.addEventListener('click', async () => {
        const row = b.closest('[data-relationship-row]') || b.parentElement;
        clearInlineActionError(row);
        const resetAction = beginButtonAction(b, 'Sending…');
        if (!resetAction) return;
        try {
          await api('/friends/request', { method: 'POST', body: JSON.stringify({ user_id: Number(b.dataset.addFriend) }) });
          toast('Friend request sent');
          state.chatFriendsCache = null;
          renderChat();
        } catch (e) {
          resetAction();
          showInlineActionError(row, e.message);
        }
      });
    });
    bindUserButtons(el);

    let timer;
    let playerSearchSeq = 0;
    const search = el.querySelector('#friend-search');
    if (!search) return;
    const bindPlayerSearchActions = (resultsEl) => {
      bindUserButtons(resultsEl);
      resultsEl.querySelectorAll('[data-msg]').forEach((button) => button.addEventListener('click', () => {
        openThread(Number(button.dataset.msg));
      }));
      resultsEl.querySelectorAll('[data-add-friend]').forEach((b) => b.addEventListener('click', async () => {
        const row = b.closest('[data-relationship-row]') || b.parentElement;
        clearInlineActionError(row);
        const resetAction = beginButtonAction(b, 'Sending…');
        if (!resetAction) return;
        try {
          await api('/friends/request', { method: 'POST', body: JSON.stringify({ user_id: Number(b.dataset.addFriend) }) });
          toast('Friend request sent!');
          // Keep the query and the rest of its results intact. Rebuilding the
          // People lane here made adding several players needlessly repetitive.
          patchVisibleFriendRelationship(Number(b.dataset.addFriend), 'pending');
        } catch (e) {
          resetAction();
          showInlineActionError(row, e.message);
        }
      }));
      resultsEl.querySelectorAll('[data-respond-inline]').forEach((b) => b.addEventListener('click', async () => {
        const row = b.closest('[data-relationship-row]') || b.parentElement;
        clearInlineActionError(row);
        const resetAction = beginButtonAction(b, 'Accepting…');
        if (!resetAction) return;
        try {
          await api(`/friends/${b.dataset.respondInline}/respond`, { method: 'POST', body: JSON.stringify({ accept: true }) });
          toast('Friend added');
          const acceptedUserId = Number(row.querySelector('[data-view-user]')?.dataset.viewUser);
          patchVisibleFriendRelationship(acceptedUserId, 'accepted');
          refreshMe();
        } catch (e) {
          resetAction();
          showInlineActionError(row, e.message);
        }
      }));
    };
    const runPlayerSearch = async (q) => {
      const seq = ++playerSearchSeq;
      let resultsEl = el.querySelector('#friend-search-results');
      if (!resultsEl || !search.isConnected) return;
      if (q.length < 2) {
        resultsEl.replaceChildren();
        resultsEl.removeAttribute('aria-busy');
        return;
      }
      resultsEl.setAttribute('aria-busy', 'true');
      resultsEl.innerHTML = `<div class="player-search-status" role="status">${uiIcon('search')} Looking for players…</div>`;
      try {
        const data = await api(`/users/search?q=${encodeURIComponent(q)}`);
        if (seq !== playerSearchSeq || !search.isConnected || search.value.trim() !== q) return;
        resultsEl = el.querySelector('#friend-search-results');
        if (!resultsEl) return;
        resultsEl.innerHTML = data.items.map((u) => {
          let action;
          if (u.friendship_status === 'accepted') action = `<span class="tag" style="margin:0">${uiIcon('check-circle')} Friends</span>`;
          else if (u.friendship_status === 'pending') action = u.outgoing ? '<span class="tag" style="margin:0">Pending</span>' : `<button class="btn btn-primary btn-sm" data-respond-inline="${u.friendship_id}">${uiIcon('check-circle')} Accept</button>`;
          else action = `<button class="btn btn-primary btn-sm" data-add-friend="${u.id}">${uiIcon('plus')} Add</button>`;
          return `
            <div class="card row" style="margin:8px 0" data-relationship-row>
              <button type="button" class="player-profile-link" data-view-user="${u.id}" aria-label="View ${esc(u.display_name)}'s profile">
                ${avatarHtml(u)}
                <span class="row-main">
                  <span class="row-title">${esc(u.display_name)}</span>
                  <span class="row-sub">${playerSkillIdentityHtml(u)}</span>
                </span>
              </button>
              <div class="friend-search-actions">
                <button type="button" class="btn btn-secondary btn-sm" data-msg="${u.id}">${uiIcon('message')} Message</button>
                ${action}
              </div>
            </div>`;
        }).join('') || '<div class="empty-state" style="padding:12px">No players found.</div>';
        bindPlayerSearchActions(resultsEl);
      } catch (error) {
        if (seq !== playerSearchSeq || !search.isConnected || search.value.trim() !== q) return;
        resultsEl = el.querySelector('#friend-search-results');
        if (resultsEl) renderError(resultsEl, error.message, () => runPlayerSearch(search.value.trim()));
      } finally {
        if (seq === playerSearchSeq) el.querySelector('#friend-search-results')?.removeAttribute('aria-busy');
      }
    };
    search.addEventListener('input', () => {
      clearTimeout(timer);
      playerSearchSeq += 1;
      const q = search.value.trim();
      const resultsEl = el.querySelector('#friend-search-results');
      if (q.length < 2) {
        resultsEl?.replaceChildren();
        resultsEl?.removeAttribute('aria-busy');
        return;
      }
      if (resultsEl) {
        resultsEl.setAttribute('aria-busy', 'true');
        resultsEl.innerHTML = `<div class="player-search-status" role="status">${uiIcon('search')} Looking for players…</div>`;
      }
      timer = setTimeout(() => runPlayerSearch(q), 300);
    });
  }

  async function openThread(userId, { draft = '' } = {}) {
    const shell = openChatLoadShell({
      route: { kind: 'chat', id: userId },
      title: 'Opening conversation',
      copy: 'Loading the latest messages…',
      label: 'Loading direct conversation',
    });
    if (!shell) return;
    const { modal, load: modalLoad } = shell;
    let data;
    try { data = await api(`/chat/${userId}`); } catch (e) {
      if (!routedOverlayLoadIsCurrent(modalLoad) || !modal.isConnected) return;
      renderDetailLoadError(
        shell,
        e.message || 'This conversation could not load.',
        () => retryDetailLoad(shell, () => openThread(userId, { draft })),
        'Conversation could not load',
      );
      return modal;
    }
    if (!routedOverlayLoadIsCurrent(modalLoad) || !modal.isConnected) return;
    state.activeThreadUserId = userId;

    hydrateChatLoadShell(shell, `
      <div class="thread">
        <div class="thread-head">
          <button type="button" class="modal-close" aria-label="Back">${uiIcon('arrow-left')}</button>
          <button type="button" class="thread-profile-link" id="thread-profile" aria-label="View ${esc(data.user.display_name)}’s profile">
            ${avatarHtml(data.user, 'sm', 'span')}
            <span class="row-main">
              <span class="row-title">${esc(data.user.display_name)}</span>
              <span class="row-sub">${data.message_request ? 'Message request · ' : ''}${data.user.active_now ? '<span class="community-presence-status"><span class="community-presence-dot" aria-hidden="true"></span>Active now</span> · ' : ''}${playerSkillIdentityHtml(data.user)}</span>
            </span>
          </button>
          <details class="thread-more-actions">
            <summary aria-label="Conversation actions" aria-haspopup="menu" aria-expanded="false">${uiIcon('sliders')}</summary>
            <div class="thread-more-menu" role="menu" aria-label="Conversation actions">
              <button type="button" class="btn btn-secondary btn-block" role="menuitem" data-thread-action="profile">${uiIcon('user')} View profile</button>
              <button type="button" class="btn btn-secondary btn-block" role="menuitem" data-thread-action="mute">${uiIcon('bell')} ${data.muted ? 'Unmute' : 'Mute'} alerts</button>
              <button type="button" class="btn btn-secondary btn-block" role="menuitem" data-thread-action="block">${uiIcon('lock')} Block player</button>
              <button type="button" class="btn btn-secondary btn-block" role="menuitem" data-thread-action="report">${uiIcon('alert-triangle')} Report</button>
            </div>
          </details>
        </div>
        <div class="thread-msgs" id="thread-msgs" role="log" aria-live="off" aria-relevant="additions" aria-label="Conversation with ${esc(data.user.display_name)}"></div>
        <form class="thread-input" id="thread-form">
          <button type="button" id="thread-photo" aria-label="Send a photo" style="background:transparent;padding:0 2px">${uiIcon('camera')}</button>
          <input type="file" id="thread-file" accept="image/*" class="hidden" />
          <textarea id="thread-text" aria-label="Message ${esc(data.user.display_name)}" placeholder="Message…" autocomplete="off" maxlength="2000" rows="1"></textarea>
          <button type="submit" aria-label="Send">${uiIcon('send')}</button>
        </form>
      </div>
    `, `Conversation with ${data.user.display_name}`);

    const msgsEl = modal.querySelector('#thread-msgs');
    const input = modal.querySelector('#thread-text');
    bindDisclosureMenus(modal);
    modal.querySelector('#thread-profile')?.addEventListener('click', () => {
      openChildModal(modal, () => openUserProfile(userId));
    });
    modal.querySelector('[data-thread-action="profile"]')?.addEventListener('click', () => {
      modal.querySelector('.thread-more-actions')?.removeAttribute('open');
      openChildModal(modal, () => openUserProfile(userId));
    });
    modal.querySelector('[data-thread-action="mute"]')?.addEventListener('click', async (event) => {
      const button = event.currentTarget;
      const nextMuted = !data.muted;
      const reset = beginButtonAction(button, nextMuted ? 'Muting…' : 'Unmuting…');
      if (!reset) return;
      try {
        const preference = await api(`/chat/${userId}/settings`, {
          method: 'PUT', body: JSON.stringify({ muted: nextMuted }),
        });
        data.muted = preference.muted === true;
        button.innerHTML = `${uiIcon('bell')} ${data.muted ? 'Unmute' : 'Mute'} alerts`;
        button.disabled = false;
        button.removeAttribute('aria-busy');
        state.chatFriendsCache = null;
        refreshMe();
        toast(data.muted ? 'Conversation alerts muted' : 'Conversation alerts unmuted');
      } catch (error) {
        reset();
        toast(error.message);
      }
    });
    modal.querySelector('[data-thread-action="block"]')?.addEventListener('click', async (event) => {
      const button = event.currentTarget;
      modal.querySelector('.thread-more-actions')?.removeAttribute('open');
      if (!await openActionConfirmation({
        eyebrow: 'Privacy & safety',
        title: `Block ${data.user.display_name}?`,
        message: 'You will no longer see each other in search, nearby players, or messages.',
        detail: 'You can unblock this player later from Privacy & safety in Settings.',
        confirmLabel: 'Block player',
        cancelLabel: 'Keep conversation',
        icon: 'lock',
        trigger: button,
      })) return;
      const reset = beginButtonAction(button, 'Blocking…');
      if (!reset) return;
      try {
        await api(`/users/${userId}/block`, { method: 'POST' });
        state.chatFriendsCache = null;
        closeModal(modal);
        toast('Player blocked');
        renderChat();
      } catch (error) {
        reset();
        toast(error.message);
      }
    });
    modal.querySelector('[data-thread-action="report"]')?.addEventListener('click', () => {
      modal.querySelector('.thread-more-actions')?.removeAttribute('open');
      openUserSafetyReport(data.user, {
        parentModal: modal,
        onBlocked: () => {
          closeModal(modal);
          renderChat();
        },
      });
    });
    const chatUX = bindChatContinuity(modal, msgsEl, input, `dm:${userId}`);
    if (draft && !input.value) {
      const limit = Number(input.maxLength) > 0 ? Number(input.maxLength) : 2000;
      input.value = String(draft).slice(0, limit);
      input.dispatchEvent(new Event('input', { bubbles: true }));
      queueMicrotask(() => {
        if (!input.isConnected) return;
        input.focus({ preventScroll: true });
        input.setSelectionRange(input.value.length, input.value.length);
      });
    }
    let lastId = 0;
    const renderMsgs = (items, append, { forceBottom = false, newMessages = false, prepend = false } = {}) => {
      const batch = prepareChatRenderBatch(msgsEl, items, append || prepend);
      if (batch.newestId) lastId = Math.max(lastId, batch.newestId);
      items = batch.items;
      if ((append || prepend) && !items.length) return;
      const snapshot = chatUX.captureScroll();
      const html = items.map((m) => {
        const mine = m.sender_id === state.me.id;
        return `
        <div class="chat-message-row ${mine ? 'is-mine' : 'is-theirs'}" data-message-row="${m.id}" data-message-created-at="${esc(m.created_at)}" style="display:flex;gap:6px;align-self:${mine ? 'flex-end' : 'flex-start'};max-width:85%;align-items:flex-end">
        <div class="bubble ${mine ? 'me' : 'them'}" data-message-id="${m.id}">
          ${m.has_image ? `<div data-img-id="${m.id}" class="chat-image-loading" style="margin-bottom:${m.body ? '6px' : '0'}" aria-hidden="true"><span class="spinner"></span></div>` : ''}
          ${chatBodyHtml(m.body)}
          <div class="bubble-time">${fmtMessageTimestamp(m.created_at)}${mine && m.read_at ? ` · <span title="Seen" class="chat-seen">${uiIcon('check-circle')}<span class="sr-only">Seen</span></span>` : ''}</div>
          ${m.hearted ? '<span class="bubble-heart">❤️</span>' : ''}
        </div>
        ${chatMessageActionHtml(m, mine)}
        </div>`;
      }).join('');
      if (prepend) { msgsEl.querySelector('.empty-state')?.remove(); msgsEl.insertAdjacentHTML('afterbegin', html); }
      else if (append && !msgsEl.querySelector('.empty-state')) msgsEl.insertAdjacentHTML('beforeend', html);
      else if (append) msgsEl.innerHTML = html;
      else msgsEl.innerHTML = html || '<div class="empty-state" style="padding:20px">Say hi and start planning your next game.</div>';
      normalizeChatDaySeparators(msgsEl);
      chatUX.restoreScroll(snapshot, { forceBottom, newMessageCount: newMessages ? items.length : 0, preserveAnchor: prepend });
      hydrateChatImages(msgsEl, chatUX);
    };
    // Add the same product-icon status to already-rendered bubbles as the partner reads.
    const markSeen = (upTo) => {
      if (!upTo) return;
      msgsEl.querySelectorAll('.bubble.me[data-message-id]').forEach((b) => {
        const t = b.querySelector('.bubble-time');
        if (Number(b.dataset.messageId) <= upTo && t && !t.querySelector('.chat-seen')) {
          t.insertAdjacentHTML('beforeend', ` · <span title="Seen" class="chat-seen">${uiIcon('check-circle')}<span class="sr-only">Seen</span></span>`);
        }
      });
    };
    // Live ❤️: the partner's hearts land on my rendered bubbles each poll.
    const applyHearts = (ids) => {
      if (!ids) return;
      const set = new Set(ids);
      msgsEl.querySelectorAll('.bubble.me[data-message-id]').forEach((b) => {
        const has = b.querySelector('.bubble-heart');
        const want = set.has(Number(b.dataset.messageId));
        if (want && !has) b.insertAdjacentHTML('beforeend', '<span class="bubble-heart">❤️</span>');
        if (!want && has) has.remove();
      });
    };
    renderMsgs(data.items, false, { forceBottom: true });
    attachChatHistoryLoader(
      modal, msgsEl, data,
      (beforeId) => api(`/chat/${userId}?before_id=${beforeId}&limit=100`),
      (items) => renderMsgs(items, false, { prepend: true }),
    );
    chatUX.activateOutbox((message) => renderMsgs([message], true, { forceBottom: true }));
    markSeen(data.partner_read_up_to);
    applyHearts(data.hearted_ids);
    refreshMe();
    stopThreadPolling();
    const threadPoller = startAdaptiveChatPoll(modal, msgsEl, async () => {
      const fresh = await api(`/chat/${userId}?since_id=${lastId}`);
      if (fresh.items.length) renderMsgs(fresh.items, true, { newMessages: true });
      applyRoomHearts(msgsEl, fresh.heart_counts);
      markSeen(fresh.partner_read_up_to);
      applyHearts(fresh.hearted_ids);
      return fresh.items.length > 0;
    });
    state.threadPollTimer = threadPoller;
    modal._cleanupFns?.push(() => {
      if (state.threadPollTimer === threadPoller) state.threadPollTimer = null;
    });

    modal.querySelector('#thread-form').addEventListener('submit', async (e) => {
      e.preventDefault();
      const body = input.value.trim();
      if (!body) return;
      try {
        await chatUX.send(body);
      } catch (err) { toast(err.message); }
    });
    modal.querySelector('#thread-photo').addEventListener('click', () => {
      const picker = modal.querySelector('#thread-file');
      if (picker.value) picker.value = '';
      picker.click();
    });
    modal.querySelector('#thread-file').addEventListener('change', async (e) => {
      const file = e.target.files[0];
      if (!file) return;
      try {
        const image = await imageFileToDataUrl(file, 1024);
        const textEl = modal.querySelector('#thread-text');
        const body = textEl.value.trim();
        await chatUX.send(body, { image });
        e.target.value = '';
      } catch (err) {
        if (err.message === 'image_too_large' || err.message === 'bad_image') e.target.value = '';
        toast(err.message === 'image_too_large' ? 'That photo is too large — try a smaller one' : err.message);
      }
    });
    return modal;
  }

  function courtOpenCallFingerprint(call) {
    return JSON.stringify([
      call.id, call.state, call.active, call.scheduled_at, call.player_count,
      call.max_players, call.spots_left, call.waitlist_count, call.is_joined,
      call.can_join, call.can_waitlist, call.can_withdraw,
    ]);
  }

  function courtOpenCallCardHtml(call) {
    const stateName = ['open', 'full', 'closed', 'withdrawn'].includes(call.state)
      ? call.state : 'closed';
    const stateLabel = {
      open: 'Open', full: 'Full', closed: 'Closed', withdrawn: 'Withdrawn',
    }[stateName];
    const playNoun = call.game_type === 'ranked' ? 'ranked match' : 'play session';
    const title = stateName === 'open'
      ? `${call.spots_left} spot${call.spots_left === 1 ? '' : 's'} left`
      : stateName === 'full' ? 'Roster is full'
        : stateName === 'withdrawn' ? 'Removed from Court chat' : 'Session closed';
    const skillRange = gameLevelRangeLabel(call);
    const skill = skillRange !== 'Any level'
      ? ` · Self-rating ${skillRange.replace(/ level$/, '')}` : '';
    const primary = call.can_join
      ? `<button type="button" class="btn btn-primary" data-open-call-action="join" data-open-call-game="${call.game_id}">Join ${playNoun}</button>`
      : call.can_waitlist
        ? `<button type="button" class="btn btn-primary" data-open-call-action="waitlist" data-open-call-game="${call.game_id}">Join waitlist</button>`
        : `<button type="button" class="btn btn-secondary" data-open-call-action="open" data-open-call-game="${call.game_id}">${call.is_joined && ['open', 'full'].includes(stateName) ? `Open your ${playNoun}` : `View ${playNoun}`}</button>`;
    return `<article class="court-open-call is-${stateName}" data-open-call-id="${call.id}"
      data-open-call-fingerprint="${esc(courtOpenCallFingerprint(call))}">
      <div class="court-open-call-head">
        <span class="court-open-call-icon" aria-hidden="true">${stateName === 'full' ? uiIcon('check-circle') : stateName === 'open' ? uiIcon('pickleball') : uiIcon('x')}</span>
        <div class="court-open-call-title"><b>${esc(title)}</b>
          <span>${esc(fmtDateTime(call.scheduled_at))} · ${call.game_type === 'ranked' ? 'Ranked match' : 'Casual play'}${esc(skill)}</span>
        </div>
        <span class="court-open-call-state">${stateLabel}</span>
      </div>
      <div class="court-open-call-capacity">
        <span><b>${call.player_count}/${call.max_players}</b> players</span>
        <span><b>${call.waitlist_count || 0}</b> waiting</span>
      </div>
      <div class="court-open-call-actions">${primary}
        ${call.can_withdraw ? `<button type="button" class="court-open-call-withdraw" data-open-call-action="withdraw" data-open-call-game="${call.game_id}" aria-label="Remove opening from Court chat">Remove</button>` : ''}
      </div>
    </article>`;
  }

  function courtOpenCallMessageHtml(message) {
    return `<div data-message-id="${message.id}" class="court-open-call-message">
      <div class="court-open-call-byline">
        <div class="avatar sm" style="background:${esc(message.sender_color)}">${esc(initials(message.sender_name))}</div>
        <span>${esc(message.sender_name)} · ${fmtMessageTimestamp(message.created_at)}</span>
      </div>
      ${courtOpenCallCardHtml(message.open_call)}
    </div>`;
  }

  function applyCourtOpenCallSnapshots(msgsEl, rawCalls, { prune = true } = {}) {
    const calls = Array.isArray(rawCalls) ? rawCalls : [];
    const byId = new Map(calls.map((call) => [Number(call.id), call]));
    let changed = false;
    msgsEl.querySelectorAll('[data-open-call-id]').forEach((card) => {
      const call = byId.get(Number(card.dataset.openCallId));
      if (!call) {
        if (prune) {
          card.closest('[data-message-id]')?.remove();
          changed = true;
        }
        return;
      }
      if (card.dataset.openCallFingerprint !== courtOpenCallFingerprint(call)) {
        card.outerHTML = courtOpenCallCardHtml(call);
        changed = true;
      }
      byId.delete(Number(call.id));
    });
    return changed;
  }

  async function openCourtChat(court) {
    if (!state.me || !state.token) return null;
    const privacyKey = `pp_court_chat_privacy:${state.me.id}:${court.id}`;
    let privacySeen = false;
    try { privacySeen = localStorage.getItem(privacyKey) === '1'; } catch { /* storage is optional */ }
    if (!privacySeen) {
      const continued = await openActionConfirmation({
        eyebrow: 'Public conversation',
        title: 'Court chat is public',
        message: 'Anyone signed in to Third Shot can read and post here — you do not need to be at the court.',
        detail: 'Your profile name appears with messages you send. Join the room only if you want it in your Inbox.',
        confirmLabel: 'Continue to court chat',
        cancelLabel: 'Not now',
        icon: 'message',
      });
      if (!continued) return null;
      try { localStorage.setItem(privacyKey, '1'); } catch { /* show again if storage is unavailable */ }
    }
    const shell = openChatLoadShell({
      title: 'Opening court chat',
      copy: `Loading the latest conversation at ${court.name || 'this court'}…`,
      label: 'Loading court chat',
    });
    if (!shell) return;
    const { modal, load: modalLoad } = shell;
    let data;
    try { data = await api(`/courts/${court.id}/chat`); } catch (e) {
      if (!routedOverlayLoadIsCurrent(modalLoad) || !modal.isConnected) return;
      renderDetailLoadError(
        shell,
        e.message || 'Court chat could not load.',
        () => retryDetailLoad(shell, () => openCourtChat(court)),
        'Court chat could not load',
      );
      return modal;
    }
    if (!routedOverlayLoadIsCurrent(modalLoad) || !modal.isConnected) return;
    refreshMe(); // keep the global Community badge exact outside Inbox
    let subscription = data.subscription || {
      joined: false, muted: false, joined_at: null, muted_at: null,
    };

    hydrateChatLoadShell(shell, `
      <div class="thread">
        <div class="thread-head">
          <button type="button" class="modal-close" aria-label="Back">${uiIcon('arrow-left')}</button>
          <span aria-hidden="true">${uiIcon('map-pin')}</span>
          <div class="row-main">
            <div class="row-title">${esc(court.name)}</div>
            <div class="row-sub">Public room — anyone on Third Shot can read and post.</div>
          </div>
          <div class="court-chat-subscription" id="cc-subscription" aria-live="polite"></div>
        </div>
        <div class="thread-msgs" id="cc-msgs" role="log" aria-live="off" aria-relevant="additions" aria-label="${esc(court.name)} court conversation"></div>
        <form class="thread-input" id="cc-form">
          <textarea id="cc-text" aria-label="Message court chat" placeholder="Write a message…" autocomplete="off" maxlength="2000" rows="1"></textarea>
          <button type="submit" aria-label="Send">${uiIcon('send')}</button>
        </form>
      </div>
    `, `${court.name || 'Court'} chat`);

    const msgsEl = modal.querySelector('#cc-msgs');
    const input = modal.querySelector('#cc-text');
    const subscriptionEl = modal.querySelector('#cc-subscription');
    const renderSubscription = () => {
      subscriptionEl.innerHTML = subscription.joined
        ? `<button type="button" class="btn btn-secondary btn-sm" data-cc-subscription="mute">${uiIcon('bell')} ${subscription.muted ? 'Unmute' : 'Mute'}</button><button type="button" class="btn btn-secondary btn-sm" data-cc-subscription="leave">Leave</button>`
        : `<button type="button" class="btn btn-secondary btn-sm" data-cc-subscription="join">${uiIcon('plus')} Join</button>`;
    };
    renderSubscription();
    subscriptionEl.addEventListener('click', async (event) => {
      const button = event.target.closest('[data-cc-subscription]');
      if (!button || button.disabled) return;
      const action = button.dataset.ccSubscription;
      if (action === 'leave' && !await openActionConfirmation({
        eyebrow: 'Court chat',
        title: 'Leave this room?',
        message: 'It will leave your Inbox and stop unread badges. You can still open the public room from the court page.',
        confirmLabel: 'Leave room',
        cancelLabel: 'Stay joined',
        icon: 'message',
        trigger: button,
      })) return;
      [...subscriptionEl.querySelectorAll('button')].forEach((item) => { item.disabled = true; });
      try {
        const payload = action === 'leave'
          ? { joined: false }
          : { joined: true, muted: action === 'mute' ? !subscription.muted : false };
        subscription = await api(`/courts/${court.id}/chat/subscription`, {
          method: 'PUT', body: JSON.stringify(payload),
        });
        renderSubscription();
        refreshMe();
        toast(action === 'join' ? 'Court chat joined'
          : action === 'leave' ? 'Left court chat'
          : subscription.muted ? 'Court chat muted' : 'Court chat unmuted');
      } catch (error) {
        renderSubscription();
        toast(error.message);
      }
    });
    const chatUX = bindChatContinuity(modal, msgsEl, input, `court:${court.id}`);
    let lastId = 0;
    const renderMsgs = (items, append, { forceBottom = false, newMessages = false, prepend = false } = {}) => {
      const batch = prepareChatRenderBatch(msgsEl, items, append || prepend);
      if (batch.newestId) lastId = Math.max(lastId, batch.newestId);
      items = batch.items;
      if ((append || prepend) && !items.length) return;
      const snapshot = chatUX.captureScroll();
      const html = items.map((m) => {
        if (m.open_call) return courtOpenCallMessageHtml(m);
        const mine = m.sender_id === state.me.id;
        return `
        <div class="chat-message-row ${mine ? 'is-mine' : 'is-theirs'}" data-message-row="${m.id}" data-message-created-at="${esc(m.created_at)}" style="display:flex;gap:8px;align-self:${mine ? 'flex-end' : 'flex-start'};max-width:85%">
          ${mine ? '' : `<div class="avatar sm" style="background:${esc(m.sender_color)}">${esc(initials(m.sender_name))}</div>`}
          <div class="bubble ${mine ? 'me' : 'them'}" data-message-id="${m.id}" style="max-width:100%">${m.heart_count ? `<span class="bubble-heart" data-heart-badge>❤️${m.heart_count > 1 ? ' ' + m.heart_count : ''}</span>` : ''}
            ${mine ? '' : `<div style="font-size:var(--text-xs);font-weight:700;opacity:.75;margin-bottom:2px">${esc(m.sender_name)}</div>`}
            ${m.has_image ? `<div data-img-id="${m.id}" class="chat-image-loading" style="margin-bottom:${m.body ? '6px' : '0'}" aria-hidden="true"><span class="spinner"></span></div>` : ''}
            ${chatBodyHtml(m.body)}
            <div class="bubble-time">${fmtMessageTimestamp(m.created_at)}</div>
          </div>
          ${chatMessageActionHtml(m, mine)}
        </div>`;
      }).join('');
      if (prepend) { msgsEl.querySelector('.empty-state')?.remove(); msgsEl.insertAdjacentHTML('afterbegin', html); }
      else if (append && !msgsEl.querySelector('.empty-state')) msgsEl.insertAdjacentHTML('beforeend', html);
      else if (append) msgsEl.innerHTML = html;
      else msgsEl.innerHTML = html || '<div class="empty-state" style="padding:20px">No messages yet — say hi to the court! 👋</div>';
      normalizeChatDaySeparators(msgsEl);
      chatUX.restoreScroll(snapshot, { forceBottom, newMessageCount: newMessages ? items.length : 0, preserveAnchor: prepend });
      hydrateChatImages(msgsEl, chatUX);
    };
    renderMsgs(data.items, false, { forceBottom: true });
    attachChatHistoryLoader(
      modal, msgsEl, data,
      (beforeId) => api(`/courts/${court.id}/chat?before_id=${beforeId}&limit=60`),
      (items) => renderMsgs(items, false, { prepend: true }),
    );
    chatUX.activateOutbox((message) => renderMsgs([message], true, { forceBottom: true }));
    addPhotoToComposer(modal, '#cc-form', '#cc-text', chatUX);

    startAdaptiveChatPoll(modal, msgsEl, async () => {
      const fresh = await api(`/courts/${court.id}/chat?since_id=${lastId}`);
      if (fresh.items.length) renderMsgs(fresh.items, true, { newMessages: true });
      applyRoomHearts(msgsEl, fresh.heart_counts);
      const callChanged = applyCourtOpenCallSnapshots(msgsEl, fresh.open_calls);
      return fresh.items.length > 0 || callChanged;
    });

    msgsEl.addEventListener('click', async (event) => {
      const button = event.target.closest('[data-open-call-action]');
      if (!button || button.disabled) return;
      const gameId = Number(button.dataset.openCallGame);
      const action = button.dataset.openCallAction;
      if (!gameId) return;
      if (action === 'open') { openChildModal(modal, () => openGameScreen(gameId)); return; }
      button.disabled = true;
      const originalText = button.textContent;
      button.textContent = action === 'join' ? 'Joining…'
        : action === 'waitlist' ? 'Joining waitlist…' : 'Withdrawing…';
      try {
        const response = action === 'withdraw'
          ? await api(`/games/${gameId}/open-call`, { method: 'DELETE' })
          : await api(`/games/${gameId}/${action === 'join' ? 'join' : 'waitlist'}`, { method: 'POST' });
        const nextCall = response.open_call || (response.game && response.game.open_call);
        if (nextCall) applyCourtOpenCallSnapshots(msgsEl, [nextCall], { prune: false });
        toast(action === 'join' ? "You're in!"
          : action === 'waitlist' ? "You're on the waitlist" : 'Removed from Court chat', {
          tone: 'success', icon: action === 'waitlist' ? 'clock' : 'pickleball',
        });
        refreshMe();
      } catch (error) {
        toast(error.message);
        button.disabled = false;
        button.textContent = originalText;
        try {
          const fresh = await api(`/courts/${court.id}/chat?since_id=${lastId}`);
          if (fresh.items.length) renderMsgs(fresh.items, true);
          applyCourtOpenCallSnapshots(msgsEl, fresh.open_calls);
        } catch { /* the adaptive poll will recover */ }
      }
    });

    modal.querySelector('#cc-form').addEventListener('submit', async (e) => {
      e.preventDefault();
      const body = input.value.trim();
      if (!body) return;
      try {
        await chatUX.send(body);
      } catch (err) { toast(err.message); }
    });
    return modal;
  }

  // ---------- Crews ----------
  function showCommunityInbox() {
    state.chatSeg = 'groups';
    document.querySelectorAll('#chat-segments button').forEach((button) => {
      const active = button.dataset.seg === 'groups';
      button.classList.toggle('active', active);
      button.setAttribute('aria-selected', String(active));
      button.tabIndex = active ? 0 : -1;
    });
    switchTab('chat');
    renderChat();
  }


  function crewIsOwner(crew) {
    return !!(crew && (
      crew.is_owner === true || crew.owner === true || crew.my_role === 'owner' || crew.role === 'owner'
      || Number(crew.owner_id || crew.creator_id) === Number(state.me && state.me.id)
    ));
  }

  async function openCreatePlayGroupSheet() {
    const presetCourt = state.presence && state.presence.checked_in ? {
      id: state.presence.court_id, name: state.presence.court_name,
    } : state.me && state.me.home_court_id ? {
      id: state.me.home_court_id, name: state.me.home_court_name || 'Primary court',
    } : null;
    const modal = openModal(`
      ${modalHead('Start a play group')}
      <p class="play-group-intro">Create a private, invite-only group for the people you want to play with again. Everyone chooses whether to join.</p>
      <form id="play-group-form" novalidate>
        <div class="form-field">
          <label for="pg-name">Group name</label>
          <input type="text" id="pg-name" maxlength="80" placeholder="e.g. Saturday morning regulars" autocomplete="off" />
        </div>
        <div class="form-field">
          <label for="pg-court-search">Default court <span class="row-sub">(optional)</span></label>
          <input type="search" id="pg-court-search" placeholder="Search courts…" autocomplete="off" value="${presetCourt ? esc(presetCourt.name) : ''}" ${presetCourt ? `data-selected-court-name="${esc(presetCourt.name)}" data-selected-court-id="${presetCourt.id}"` : ''} />
          <input type="hidden" id="pg-court-id" value="${presetCourt ? presetCourt.id : ''}" />
          <div id="pg-court-results" style="margin-top:8px"></div>
        </div>
        <fieldset class="play-group-friends">
          <legend>Invite friends</legend>
          <p>Choose one or more friends. They will receive a play-group invitation.</p>
          <div id="pg-friends" class="play-group-friend-grid" aria-live="polite" aria-busy="true">${skeletonHtml(3)}</div>
        </fieldset>
        <p class="row-sub play-group-selection" id="pg-selection" role="status">Choose at least one friend.</p>
        <button type="submit" class="btn btn-primary btn-block" id="pg-submit">Start play group</button>
      </form>
    `, { label: 'Start a private play group' });
    clubCourtPicker(modal, 'pg');
    const formUX = bindModalFormUX(modal, '#pg-submit', { draftKey: 'create-play-group' });
    const list = modal.querySelector('#pg-friends');
    const selection = modal.querySelector('#pg-selection');
    const submit = modal.querySelector('#pg-submit');
    const selectedIds = new Set();
    let friends = [];
    let friendsReady = false;
    const syncSelection = () => {
      selection.textContent = selectedIds.size
        ? `${selectedIds.size} friend${selectedIds.size === 1 ? '' : 's'} selected · they choose whether to join.`
        : friendsReady ? 'Choose at least one friend.' : 'Loading friends…';
      submit.disabled = !friendsReady || !friends.length || !selectedIds.size;
      modal.querySelectorAll('[data-play-group-friend]').forEach((button) => {
        const active = selectedIds.has(Number(button.dataset.playGroupFriend));
        button.classList.toggle('active', active);
        button.setAttribute('aria-pressed', String(active));
      });
    };
    const loadFriends = async () => {
      friendsReady = false;
      submit.disabled = true;
      selection.textContent = 'Loading friends…';
      list.setAttribute('aria-busy', 'true');
      list.innerHTML = skeletonHtml(3);
      try {
        const response = await api('/friends');
        if (!document.body.contains(modal)) return;
        friends = Array.isArray(response.friends) ? response.friends : [];
        friendsReady = true;
        const liveIds = new Set(friends.map((friend) => Number(friend.id)));
        [...selectedIds].forEach((id) => { if (!liveIds.has(id)) selectedIds.delete(id); });
        list.removeAttribute('aria-busy');
        list.innerHTML = friends.length ? friends.map((friend) => `
          <button type="button" class="play-group-friend" data-play-group-friend="${friend.id}" aria-pressed="false">
            ${avatarHtml(friend, 'sm')}
            <span><b>${esc(friend.display_name)}</b><small>${playerSkillIdentityHtml(friend)}</small></span>
            <span class="play-group-check" aria-hidden="true">${uiIcon('check')}</span>
          </button>`).join('')
          : '<div class="empty-state" style="padding:18px">Add friends from Community first, then start your private play group.</div>';
        list.querySelectorAll('[data-play-group-friend]').forEach((button) => button.addEventListener('click', () => {
          const id = Number(button.dataset.playGroupFriend);
          if (selectedIds.has(id)) selectedIds.delete(id); else selectedIds.add(id);
          syncSelection();
        }));
        syncSelection();
      } catch (error) {
        if (!document.body.contains(modal)) return;
        friendsReady = false;
        submit.disabled = true;
        selection.textContent = 'Friends could not load. Try again below.';
        list.removeAttribute('aria-busy');
        renderError(list, error.message || 'Friends could not load.', loadFriends);
      }
    };
    modal.querySelector('#play-group-form').addEventListener('submit', async (event) => {
      event.preventDefault();
      formUX.clearError();
      if (!friendsReady) {
        formUX.showError('Wait for friends to finish loading, then try again.', list);
        return;
      }
      const name = modal.querySelector('#pg-name').value.trim();
      if (name.length < 3) {
        formUX.showError('Give your play group a name with at least 3 characters.', modal.querySelector('#pg-name'));
        return;
      }
      if (!selectedIds.size) {
        formUX.showError('Choose at least one friend to invite.', list.querySelector('button') || list);
        return;
      }
      const finish = formUX.startSubmitting('Starting group…');
      if (!finish) return;
      try {
        const response = await api('/crews', {
          method: 'POST',
          body: JSON.stringify({
            name,
            default_court_id: Number(modal.querySelector('#pg-court-id').value) || null,
            invite_user_ids: [...selectedIds],
          }),
        });
        const crew = crewSummaryFrom(response.crew || response);
        if (!crew) throw new Error('The play group was created, but could not be opened.');
        formUX.clearDraft({ disable: true });
        const requested = selectedIds.size;
        const sent = Math.max(0, Number(response.invited_count) || 0);
        const skipped = Array.isArray(response.skipped) ? response.skipped : [];
        const needsInviteReview = sent !== requested || skipped.length > 0;
        renderChat(); refreshMe();
        if (needsInviteReview) {
          finish();
          const form = modal.querySelector('#play-group-form');
          const notSent = Math.max(skipped.length, requested - sent);
          form.innerHTML = `
            <div class="planner-inline-warning" role="alert" tabindex="-1" id="pg-invite-review">
              <b>Review this play group before continuing</b>
              <span>The group was created, but ${sent} of ${requested} invitation${requested === 1 ? '' : 's'} ${sent === 1 ? 'was' : 'were'} sent. ${notSent} ${notSent === 1 ? 'person' : 'people'} could not be invited.</span>
            </div>
            <p class="row-sub">Open the group to see who is included and try Add players again if their eligibility changed.</p>
            <button type="button" class="btn btn-primary btn-block" id="pg-review-group">Review play group</button>
            <button type="button" class="btn-link modal-close btn-block">Close</button>`;
          form.querySelector('#pg-review-group').addEventListener('click', () => {
            transitionModal(modal, () => openCrewScreen(crew.id));
          });
          form.querySelector('#pg-invite-review').focus({ preventScroll: true });
          return;
        }
        toast(`Play group started · ${sent} invitation${sent === 1 ? '' : 's'} sent`);
        transitionModal(modal, () => openCrewScreen(crew.id));
      } catch (error) {
        finish();
        formUX.showError(error.message);
      }
    });
    loadFriends();
    return modal;
  }

  async function openCrewInviteSheet(crew, onSaved = null) {
    const modal = openModal(`
      ${modalHead(`Add players to ${crew.name}`)}
      <p class="play-group-intro">Invite established friends. They choose whether to join this private play group.</p>
      <form id="crew-invite-form" novalidate>
        <fieldset class="play-group-friends">
          <legend>Friends you can invite</legend>
          <div id="crew-invite-friends" class="play-group-friend-grid" aria-live="polite" aria-busy="true">${skeletonHtml(3)}</div>
        </fieldset>
        <p class="row-sub play-group-selection" id="crew-invite-selection" role="status">Choose one or more friends.</p>
        <button type="submit" class="btn btn-primary btn-block" id="crew-invite-submit">Send invitations</button>
      </form>
    `, { label: `Add players to ${crew.name}` });
    const formUX = bindModalFormUX(modal, '#crew-invite-submit');
    const list = modal.querySelector('#crew-invite-friends');
    const selection = modal.querySelector('#crew-invite-selection');
    const submit = modal.querySelector('#crew-invite-submit');
    const selectedIds = new Set();
    let candidates = [];
    let friendsReady = false;
    const syncSelection = () => {
      selection.textContent = selectedIds.size
        ? `${selectedIds.size} friend${selectedIds.size === 1 ? '' : 's'} selected.`
        : friendsReady ? 'Choose one or more friends.' : 'Loading friends…';
      submit.disabled = !friendsReady || !candidates.length || !selectedIds.size;
      list.querySelectorAll('[data-crew-invite-friend]').forEach((button) => {
        const active = selectedIds.has(Number(button.dataset.crewInviteFriend));
        button.classList.toggle('active', active);
        button.setAttribute('aria-pressed', String(active));
      });
    };
    const loadFriends = async () => {
      friendsReady = false;
      submit.disabled = true;
      selection.textContent = 'Loading friends…';
      list.setAttribute('aria-busy', 'true');
      list.innerHTML = skeletonHtml(3);
      try {
        const response = await api('/friends');
        if (!document.body.contains(modal)) return;
        const unavailable = new Set([
          ...(crew.members || []).map((member) => Number(member.id ?? member.user_id)),
          ...(crew.pending_invites || []).map((invite) => Number(invite.user && invite.user.id)),
        ].filter(Number.isSafeInteger));
        candidates = (response.friends || []).filter((friend) => !unavailable.has(Number(friend.id)));
        friendsReady = true;
        const liveIds = new Set(candidates.map((friend) => Number(friend.id)));
        [...selectedIds].forEach((id) => { if (!liveIds.has(id)) selectedIds.delete(id); });
        list.removeAttribute('aria-busy');
        list.innerHTML = candidates.length ? candidates.map((friend) => `
          <button type="button" class="play-group-friend" data-crew-invite-friend="${friend.id}" aria-pressed="false">
            ${avatarHtml(friend, 'sm')}
            <span><b>${esc(friend.display_name)}</b><small>${playerSkillIdentityHtml(friend)}</small></span>
            <span class="play-group-check" aria-hidden="true">${uiIcon('check')}</span>
          </button>`).join('')
          : '<div class="empty-state" style="padding:18px">Everyone eligible is already in this group or has an invitation.</div>';
        list.querySelectorAll('[data-crew-invite-friend]').forEach((button) => button.addEventListener('click', () => {
          const id = Number(button.dataset.crewInviteFriend);
          if (selectedIds.has(id)) selectedIds.delete(id); else selectedIds.add(id);
          syncSelection();
        }));
        syncSelection();
      } catch (error) {
        if (!document.body.contains(modal)) return;
        friendsReady = false;
        submit.disabled = true;
        selection.textContent = 'Friends could not load. Try again below.';
        list.removeAttribute('aria-busy');
        renderError(list, error.message || 'Friends could not load.', loadFriends);
      }
    };
    modal.querySelector('#crew-invite-form').addEventListener('submit', async (event) => {
      event.preventDefault();
      formUX.clearError();
      if (!friendsReady) {
        formUX.showError('Wait for friends to finish loading, then try again.', list);
        return;
      }
      if (!selectedIds.size) {
        formUX.showError('Choose at least one friend to invite.', list.querySelector('button') || list);
        return;
      }
      const finish = formUX.startSubmitting('Sending invitations…');
      if (!finish) return;
      try {
        const requested = selectedIds.size;
        const response = await api(`/crews/${crew.id}/invites`, {
          method: 'POST', body: JSON.stringify({ invite_user_ids: [...selectedIds] }),
        });
        const sent = Number(response.invited_count) || 0;
        const skipped = Array.isArray(response.skipped) ? response.skipped : [];
        const needsInviteReview = sent !== requested || skipped.length > 0;
        renderChat(); refreshMe();
        if (needsInviteReview) {
          finish();
          // Refresh the retained Crew detail when this child eventually
          // closes, even if the user chooses Close instead of Review group.
          onSaved?.();
          const notSent = Math.max(requested - sent, skipped.length);
          const form = modal.querySelector('#crew-invite-form');
          form.innerHTML = `
            <div class="planner-inline-warning" role="alert" tabindex="-1" id="crew-invite-review">
              <b>Review this play group before continuing</b>
              <span>${sent} of ${requested} invitation${requested === 1 ? '' : 's'} ${sent === 1 ? 'was' : 'were'} sent. ${notSent} ${notSent === 1 ? 'person' : 'people'} could not be invited.</span>
            </div>
            <p class="row-sub">Open the group to see who is included and try Add players again if their eligibility changed.</p>
            <button type="button" class="btn btn-primary btn-block" id="crew-review-group">Review play group</button>
            <button type="button" class="btn-link modal-close btn-block">Close</button>`;
          form.querySelector('#crew-review-group').addEventListener('click', () => {
            if (onSaved) closeModal(modal);
            else transitionModal(modal, () => openCrewScreen(crew.id));
          });
          form.querySelector('#crew-invite-review').focus({ preventScroll: true });
          return;
        }
        toast(sent ? `${sent} play-group invitation${sent === 1 ? '' : 's'} sent` : 'Those players are already included');
        if (onSaved) {
          onSaved();
          closeModal(modal);
        } else {
          transitionModal(modal, () => openCrewScreen(crew.id));
        }
      } catch (error) {
        finish();
        formUX.showError(error.message);
      }
    });
    loadFriends();
    return modal;
  }

  function crewPlannerOptions(crew) {
    const members = (crew.members || []).map(sanitizePlannerInvitee).filter(Boolean);
    const invitees = members.filter((person) => !state.me || person.id !== state.me.id);
    const total = invitees.length + 1;
    const maxPlayers = total <= 2 ? 2 : total <= 4 ? 4
      : Math.min(12, Math.max(6, total));
    const game = {
      id: null,
      court: crew.default_court_id ? {
        id: crew.default_court_id, name: crew.default_court_name || 'Group court',
      } : null,
      game_type: 'casual',
      max_players: maxPlayers,
      preferred_level: 'any',
      scheduled_at: null,
    };
    return {
      ...completedCrewPlannerOptions(game, invitees, crew),
      gameType: 'casual',
      lockGameType: true,
      sessionMode: true,
      maxPlayers,
    };
  }

  function renderCrewInvitationConsent(shell, invitation) {
    const { modal, box } = shell;
    const crew = crewSummaryFrom(invitation);
    if (!crew || !modal.isConnected) return false;
    const inviter = invitation.inviter?.display_name
      || invitation.invited_by_name || invitation.creator_name || 'A player';
    const courtName = invitation.source_court_name || crew.default_court_name;
    box.removeAttribute('aria-busy');
    box.innerHTML = `
      ${modalHead(crew.name)}
      <div class="community-group-eyebrow">Private play group invitation</div>
      <div class="card crew-invite-card" data-crew-invitation="${crew.id}">
        <div class="row crew-invite-main">
          <span class="inbox-room-icon crew" aria-hidden="true">${uiIcon('users')}</span>
          <span class="row-main">
            <span class="row-title">${esc(inviter)} invited you</span>
            <span class="row-sub">${courtName ? `You played together at ${esc(courtName)} · ` : ''}Private and invite only</span>
          </span>
        </div>
        <p class="row-sub" style="margin:10px 0 0">Only members can see this group’s player list, upcoming sessions, and conversation. Joining is always your choice.</p>
        <div class="crew-invite-actions">
          <button type="button" class="btn btn-secondary" data-crew-response="decline" data-crew-id="${crew.id}">${uiIcon('x')} Decline</button>
          <button type="button" class="btn btn-primary" data-crew-response="accept" data-crew-id="${crew.id}">${uiIcon('check-circle')} Join group</button>
        </div>
      </div>
    `;
    setDialogLabel(box, `${crew.name} invitation`);
    bindCrewInvitationActions(box, {
      onAccepted: () => transitionModal(modal, () => openCrewScreen(crew.id)),
      onDeclined: () => {
        clearDeadDeepLink(`#crew/${crew.id}`);
        closeModal(modal);
        showCommunityInbox();
      },
    });
    return true;
  }

  async function openCrewScreen(crewId) {
    const route = { kind: 'crew', id: crewId };
    const shell = openDetailLoadShell({
      route,
      title: 'Opening play group',
      copy: 'Loading players, court, and planning details…',
      label: 'Loading play group details',
    });
    if (!shell) return;
    const { modal, box, load: routeLoad } = shell;
    let detail;
    try { detail = await api(`/crews/${crewId}`); } catch (error) {
      if (!routedOverlayLoadIsCurrent(routeLoad) || !modal.isConnected) return;
      if (Number(error.status) === 404) {
        let pending = pendingCrewInvitationEntries().find(
          (entry) => Number(entry.crew.id) === Number(crewId),
        );
        try {
          const mine = await api('/crews/mine');
          if (!routedOverlayLoadIsCurrent(routeLoad) || !modal.isConnected) return;
          syncPendingCrewInvitesFromMine(mine);
          pending = pendingCrewInvitationEntries(mine).find(
            (entry) => Number(entry.crew.id) === Number(crewId),
          );
        } catch { /* preserve the original member-only error below */ }
        if (pending && renderCrewInvitationConsent(shell, pending.invitation)) return modal;
      }
      if ([404, 410].includes(Number(error.status))) clearDeadDeepLink(`#crew/${crewId}`);
      renderDetailLoadError(
        shell,
        error.message || 'This play group could not load.',
        () => retryDetailLoad(shell, () => openCrewScreen(crewId)),
        'Play group details could not load',
      );
      return modal;
    }
    if (!routedOverlayLoadIsCurrent(routeLoad) || !modal.isConnected) return;
    const summary = crewSummaryFrom(detail);
    if (!summary) {
      renderDetailLoadError(
        shell,
        'Play group details are unavailable.',
        () => retryDetailLoad(shell, () => openCrewScreen(crewId)),
        'Play group details could not load',
      );
      return modal;
    }
    const members = Array.isArray(detail.members) ? detail.members : [];
    const crew = { ...detail, ...summary, members };
    crew.member_count = Math.max(1, Number(detail.member_count) || members.length || summary.member_count);
    const owner = crewIsOwner(crew);
    const notificationLabel = crew.my_notification_level === 'off' ? 'Muted'
      : crew.my_notification_level === 'mentions' ? 'Mentions only' : 'All messages';
    const upcomingGames = Array.isArray(crew.upcoming_games) ? crew.upcoming_games : [];
    const upcomingGamesHtml = upcomingGames.map((game) => {
      const playerCount = Array.isArray(game.players)
        ? game.players.length : Math.max(0, Number(game.player_count) || 0);
      const spotsLeft = Math.max(0, Number(game.spots_left)
        || (Math.max(0, Number(game.max_players) || 0) - playerCount));
      return `<button type="button" class="card row nav-row-button" data-open-crew-game="${game.id}" aria-label="View play-session details at ${esc(game.court?.name || 'court')}">
        <span class="nav-row-leading">${uiIcon(game.game_type === 'ranked' ? 'trophy' : 'pickleball')}</span>
        <span class="row-main"><span class="row-title">${esc(game.court?.name || 'Court')}</span><span class="row-sub">${fmtDateTime(game.scheduled_at)} · ${playerCount}/${game.max_players} in${spotsLeft ? ` · ${spotsLeft} spot${spotsLeft === 1 ? '' : 's'} left` : ' · full'}</span></span>
        ${uiIcon('chevron-right', 'chev')}
      </button>`;
    }).join('');
    const heroContent = `
      <div class="crew-avatar-stack">${crew.members.slice(0, 4).map((member) => avatarHtml(member, 'sm')).join('')}</div>
      <div class="row-main">
        <b>${crew.member_count} player${crew.member_count === 1 ? '' : 's'}${crew.pending_count ? ` · ${crew.pending_count} invited` : ''}</b>
        <span class="row-sub">${crew.default_court_name ? `${uiIcon('map-pin', 'community-inline-icon')} ${esc(crew.default_court_name)} · Private play group · invite only` : 'Private play group · invite only'}</span>
      </div>`;
    const heroHtml = crew.default_court_id
      ? `<button type="button" class="crew-hero" id="crew-court" aria-label="Open ${esc(crew.default_court_name || 'play group court')} details">${heroContent}</button>`
      : `<div class="crew-hero">${heroContent}</div>`;
    const membersHtml = crew.members.map((member) => {
      const memberId = Number(member.id ?? member.user_id);
      const memberIsOwner = member.is_owner === true
        || member.role === 'owner' || memberId === Number(crew.owner_id || crew.creator_id);
      return `<div class="card row crew-member">
        <button type="button" class="player-profile-link" data-view-user="${memberId}" aria-label="View ${esc(member.display_name || 'player')}'s profile">
          ${avatarHtml(member, 'sm')}
          <span class="row-main"><span class="row-title">${esc(member.display_name || 'Player')}${memberIsOwner ? '<span class="community-role-tag">Owner</span>' : ''}</span><span class="row-sub">${playerSkillIdentityHtml(member)}</span></span>
          ${uiIcon('chevron-right', 'chev')}
        </button>
        ${owner && !memberIsOwner && memberId !== Number(state.me?.id) ? `<button type="button" class="btn btn-secondary btn-sm" data-crew-remove-member="${memberId}" aria-label="Remove ${esc(member.display_name || 'player')} from ${esc(crew.name)}">${uiIcon('x')}</button>` : ''}
      </div>`;
    }).join('');
    box.removeAttribute('aria-busy');
    box.innerHTML = `
      ${modalHead(crew.name)}
      ${heroHtml}
      <div class="crew-primary-actions">
        <button type="button" class="btn btn-primary" id="crew-plan">${uiIcon('calendar')} Plan with this group</button>
        <button type="button" class="btn btn-secondary" id="crew-chat">${uiIcon('message')} Group chat</button>
      </div>
      ${crew.pending_count ? `<div class="crew-pending-note">${crew.pending_count} invitation${crew.pending_count === 1 ? '' : 's'} pending. They choose whether to join.</div>` : ''}
      ${owner ? `<button type="button" class="btn btn-secondary btn-block crew-add-players" id="crew-add-players">${uiIcon('plus')} Add players</button>` : ''}
      ${upcomingGamesHtml ? `<div class="section-label">Upcoming play</div><div class="crew-upcoming-games">${upcomingGamesHtml}</div>` : '<div class="crew-pending-note">No upcoming sessions yet. Plan one when this group is ready.</div>'}
      <details class="flow-disclosure" ${crew.member_count <= 4 ? 'open' : ''}>
        <summary>Players <span>${crew.member_count}</span></summary>
        <div class="crew-roster">${membersHtml || '<div class="empty-state" style="padding:18px">No players available.</div>'}</div>
      </details>
      <details class="flow-disclosure crew-settings">
      <summary>Group settings <span>Notifications &amp; membership</span></summary>
      <div class="crew-manage-actions">
        <button type="button" class="btn btn-secondary" id="crew-notifications">${uiIcon('bell')} Notifications: ${notificationLabel}</button>
        ${owner ? `<button type="button" class="btn btn-secondary" id="crew-rename">${uiIcon('edit')} Rename</button><button type="button" class="btn btn-secondary danger-text" id="crew-delete">${uiIcon('trash')} Disband group</button>`
          : '<button type="button" class="btn btn-secondary" id="crew-leave">Leave group</button>'}
      </div>
      </details>
    `;
    modal.dataset.crewInfoId = String(crew.id);
    setDialogLabel(box, crew.name);
    bindUserButtons(modal);
    modal.querySelector('#crew-court')?.addEventListener('click', () => {
      openChildModal(modal, () => openCourtDetail(crew.default_court_id));
    });
    modal.querySelectorAll('[data-open-crew-game]').forEach((row) => row.addEventListener('click', () => {
      openChildModal(modal, () => openGameScreen(Number(row.dataset.openCrewGame)));
    }));
    modal.querySelector('#crew-plan')?.addEventListener('click', () => {
      const options = crewPlannerOptions(crew);
      if (!options.inviteUserIds.length) {
        toast('At least one player needs to join before this group can plan a session');
        return;
      }
      options.onCreated = () => {
        if (modal.isConnected) transitionModal(modal, () => openCrewScreen(crew.id));
      };
      openChildModal(modal, () => openNewGameModal(options));
    });
    modal.querySelector('#crew-add-players')?.addEventListener('click', () => {
      openChildModal(modal, () => openCrewInviteSheet(crew, () => {
        transitionModal(modal, () => openCrewScreen(crew.id));
      }));
    });
    modal.querySelector('#crew-chat')?.addEventListener('click', () => {
      openChildModal(modal, () => openCrewChat(crew));
    });
    modal.querySelector('#crew-notifications')?.addEventListener('click', () => {
      openChildModal(modal, () => openCrewNotificationSheet(crew, () => {
        transitionModal(modal, () => openCrewScreen(crew.id));
      }));
    });
    modal.querySelector('#crew-rename')?.addEventListener('click', () => {
      openChildModal(modal, () => openRenameCrewSheet(crew, () => {
        transitionModal(modal, () => openCrewScreen(crew.id));
      }));
    });
    modal.querySelectorAll('[data-crew-remove-member]').forEach((button) => button.addEventListener('click', async () => {
      const memberId = Number(button.dataset.crewRemoveMember);
      const member = crew.members.find((item) => Number(item.id ?? item.user_id) === memberId);
      if (!await openActionConfirmation({
        eyebrow: 'Play group access',
        title: `Remove ${member?.display_name || 'this player'}?`,
        message: 'They will lose access to this private group, its player list, and its conversation.',
        detail: 'Their existing game history remains unchanged. You can invite them again later.',
        confirmLabel: 'Remove player',
        cancelLabel: 'Keep player',
        icon: 'users',
        trigger: button,
      })) return;
      const resetAction = beginButtonAction(
        button, 'Removing…', [...modal.querySelectorAll('[data-crew-remove-member]')],
      );
      if (!resetAction) return;
      try {
        await api(`/crews/${crew.id}/members/${memberId}`, { method: 'DELETE' });
        toast('Player removed from the play group');
        renderChat();
        refreshMe();
        transitionModal(modal, () => openCrewScreen(crew.id));
      } catch (error) {
        resetAction();
        toast(error.message);
      }
    }));
    modal.querySelector('#crew-leave')?.addEventListener('click', async (event) => {
      const button = event.currentTarget;
      if (!await openActionConfirmation({
        eyebrow: 'Leave play group',
        title: `Leave ${crew.name}?`,
        message: 'You will lose access to this group’s private chat and future planning.',
        detail: 'Existing games remain in your history. A member can invite you again later.',
        confirmLabel: 'Leave group',
        cancelLabel: 'Stay in group',
        icon: 'users',
        trigger: button,
      })) return;
      button.disabled = true;
      try {
        await api(`/crews/${crew.id}/leave`, { method: 'POST' });
        await purgeChatOutboxChannel(state.me?.id, `crew:${crew.id}`);
        toast('You left the play group');
        closeModal(modal); renderChat(); refreshMe();
      } catch (error) { toast(error.message); button.disabled = false; }
    });
    modal.querySelector('#crew-delete')?.addEventListener('click', async (event) => {
      const button = event.currentTarget;
      if (!await openActionConfirmation({
        eyebrow: 'Disband for everyone',
        title: `Disband ${crew.name}?`,
        message: 'This deletes the private group and its shared chat for every member.',
        detail: 'Upcoming games stay intact, but this group and its conversation cannot be restored.',
        confirmLabel: 'Disband group',
        cancelLabel: 'Keep group',
        icon: 'trash',
        trigger: button,
      })) return;
      button.disabled = true;
      try {
        await api(`/crews/${crew.id}`, { method: 'DELETE' });
        await purgeChatOutboxChannel(state.me?.id, `crew:${crew.id}`);
        toast('Play group disbanded');
        closeModal(modal); renderChat(); refreshMe();
      } catch (error) { toast(error.message); button.disabled = false; }
    });
  }

  function openRenameCrewSheet(crew, onSaved = null) {
    const modal = openModal(`
      ${modalHead('Rename play group')}
      <form id="crew-rename-form" novalidate>
        <div class="form-field"><label for="crew-name">Group name</label><input id="crew-name" type="text" maxlength="80" value="${esc(crew.name)}" autocomplete="off" /></div>
        <button type="submit" class="btn btn-primary btn-block" id="crew-name-save">Save name</button>
      </form>
    `);
    const formUX = bindModalFormUX(modal, '#crew-name-save', { draftKey: `rename-crew-${crew.id}` });
    modal.querySelector('#crew-rename-form').addEventListener('submit', async (event) => {
      event.preventDefault(); formUX.clearError();
      const name = modal.querySelector('#crew-name').value.trim();
      if (name.length < 3) { formUX.showError('Group name needs 3+ characters.', modal.querySelector('#crew-name')); return; }
      const finish = formUX.startSubmitting('Saving name…');
      if (!finish) return;
      try {
        await api(`/crews/${crew.id}`, { method: 'PATCH', body: JSON.stringify({ name }) });
        formUX.clearDraft({ disable: true });
        toast('Play group renamed');
        if (onSaved) {
          onSaved();
          closeModal(modal);
        } else {
          transitionModal(modal, () => openCrewScreen(crew.id));
        }
        renderChat();
      } catch (error) { finish(); formUX.showError(error.message); }
    });
  }

  function openCrewNotificationSheet(crew, onSaved = null) {
    let selected = ['all', 'mentions', 'off'].includes(crew.my_notification_level)
      ? crew.my_notification_level : 'all';
    const modal = openModal(`
      ${modalHead('Play group notifications')}
      <p class="play-group-intro">Choose alerts for this private play group. Messages stay available whenever you open the chat.</p>
      <div class="community-notification-options" role="radiogroup" aria-label="Play group notification level">
        ${[
    ['all', 'All messages', 'Notify me when anyone posts.'],
    ['mentions', 'Mentions only', 'Notify me only when someone writes @ followed by my name.'],
    ['off', 'Mute this group', 'Keep this play group quiet until you turn alerts back on.'],
  ].map(([value, label, help]) => `<button type="button" class="choice-card ${selected === value ? 'selected' : ''}" role="radio" aria-checked="${selected === value}" data-crew-notification="${value}"><span><b>${label}</b><small>${help}</small></span>${uiIcon(selected === value ? 'check-circle' : 'circle')}</button>`).join('')}
      </div>
      <p class="form-error inline-action-error" data-inline-action-error role="alert" tabindex="-1" hidden></p>
      <button type="button" class="btn btn-primary btn-block" id="crew-notification-save">Save notification setting</button>
    `);
    const sync = () => modal.querySelectorAll('[data-crew-notification]').forEach((button) => {
      const active = button.dataset.crewNotification === selected;
      button.classList.toggle('selected', active);
      button.setAttribute('aria-checked', String(active));
      const icon = button.querySelector('.ui-icon');
      if (icon) icon.outerHTML = uiIcon(active ? 'check-circle' : 'circle');
    });
    modal.querySelectorAll('[data-crew-notification]').forEach((button) => button.addEventListener('click', () => {
      selected = button.dataset.crewNotification;
      sync();
    }));
    modal.querySelector('#crew-notification-save').addEventListener('click', async (event) => {
      clearInlineActionError(modal);
      const reset = beginButtonAction(event.currentTarget, 'Saving…');
      if (!reset) return;
      try {
        await api(`/crews/${crew.id}/notification-settings`, {
          method: 'PATCH', body: JSON.stringify({ level: selected }),
        });
        crew.my_notification_level = selected;
        dismissModal(modal);
        toast(selected === 'off' ? 'Play group muted' : 'Play group notifications updated');
        await onSaved?.();
      } catch (error) { reset(); showInlineActionError(modal, error.message); }
    });
    return modal;
  }

  async function openCrewChatById(crewId) {
    const shell = openChatLoadShell({
      route: { kind: 'crew', id: crewId },
      title: 'Opening group chat',
      copy: 'Loading the play group and its latest conversation…',
      label: 'Loading play group chat',
    });
    if (!shell) return;
    const routeLoad = shell.load;
    let detail;
    try { detail = await api(`/crews/${crewId}`); } catch (error) {
      if (!routedOverlayLoadIsCurrent(routeLoad) || !shell.modal.isConnected) return;
      renderDetailLoadError(
        shell,
        error.message || 'This play group could not load.',
        () => retryDetailLoad(shell, () => openCrewChatById(crewId)),
        'Play group chat could not load',
      );
      return shell.modal;
    }
    if (!routedOverlayLoadIsCurrent(routeLoad) || !shell.modal.isConnected) return;
    const summary = crewSummaryFrom(detail);
    if (!summary) {
      renderDetailLoadError(
        shell,
        'Play group details are unavailable.',
        () => retryDetailLoad(shell, () => openCrewChatById(crewId)),
        'Play group chat could not load',
      );
      return shell.modal;
    }
    return openCrewChat({ ...detail, ...summary }, { shell });
  }

  async function openCrewChat(crew, { shell: existingShell = null } = {}) {
    const shell = existingShell || openChatLoadShell({
      route: { kind: 'crew', id: crew.id },
      title: 'Opening group chat',
      copy: `Loading the latest conversation in ${crew.name || 'this play group'}…`,
      label: 'Loading play group chat',
    });
    if (!shell) return;
    const { modal, load: routeLoad } = shell;
    let data;
    try { data = await api(`/crews/${crew.id}/chat`); } catch (error) {
      if (!routedOverlayLoadIsCurrent(routeLoad) || !modal.isConnected) return;
      renderDetailLoadError(
        shell,
        error.message || 'Play group chat could not load.',
        () => retryDetailLoad(shell, () => openCrewChat(crew)),
        'Play group chat could not load',
      );
      return modal;
    }
    if (!routedOverlayLoadIsCurrent(routeLoad) || !modal.isConnected) return;
    refreshMe();
    hydrateChatLoadShell(shell, `
      <div class="thread">
        <div class="thread-head">
          <button type="button" class="modal-close" aria-label="Back">${uiIcon('arrow-left')}</button>
          <span class="inbox-room-icon crew" aria-hidden="true">${uiIcon('users')}</span>
          <button type="button" class="row-main crew-chat-head" id="crew-chat-head" aria-label="Open ${esc(crew.name)} play group info">
            <span class="row-title">${esc(crew.name)}</span>
            <span class="row-sub">Private play group · invite only · ${crew.member_count} player${crew.member_count === 1 ? '' : 's'} · Open group info</span>
          </button>
        </div>
        <div class="thread-msgs" id="crew-msgs" role="log" aria-live="off" aria-relevant="additions" aria-label="${esc(crew.name)} private play group conversation"></div>
        <form class="thread-input" id="crew-form">
          <textarea id="crew-text" aria-label="Message the play group" placeholder="Message the play group…" autocomplete="off" maxlength="2000" rows="1"></textarea>
          <button type="submit" aria-label="Send">${uiIcon('send')}</button>
        </form>
      </div>
    `, `${crew.name || 'Play group'} chat`);
    const msgsEl = modal.querySelector('#crew-msgs');
    const input = modal.querySelector('#crew-text');
    const chatUX = bindChatContinuity(modal, msgsEl, input, `crew:${crew.id}`);
    let lastId = 0;
    const renderMessages = (rawItems, append, { forceBottom = false, newMessages = false, prepend = false } = {}) => {
      const batch = prepareChatRenderBatch(msgsEl, rawItems || [], append || prepend);
      if (batch.newestId) lastId = Math.max(lastId, batch.newestId);
      const items = batch.items;
      if ((append || prepend) && !items.length) return;
      const snapshot = chatUX.captureScroll();
      const html = items.map((message) => {
        const mine = message.sender_id === state.me.id;
        return `<div class="chat-message-row ${mine ? 'is-mine' : 'is-theirs'}" data-message-row="${message.id}" data-message-created-at="${esc(message.created_at)}" style="display:flex;gap:8px;align-self:${mine ? 'flex-end' : 'flex-start'};max-width:85%">
          ${mine ? '' : `<div class="avatar sm" style="background:${esc(message.sender_color)}">${esc(initials(message.sender_name))}</div>`}
          <div class="bubble ${mine ? 'me' : 'them'}" data-message-id="${message.id}" style="max-width:100%">${message.heart_count ? `<span class="bubble-heart" data-heart-badge>❤️${message.heart_count > 1 ? ` ${message.heart_count}` : ''}</span>` : ''}
            ${mine ? '' : `<div style="font-size:var(--text-xs);font-weight:700;opacity:.75;margin-bottom:2px">${esc(message.sender_name)}</div>`}
            ${message.has_image ? `<div data-img-id="${message.id}" class="chat-image-loading" style="margin-bottom:${message.body ? '6px' : '0'}" aria-hidden="true"><span class="spinner"></span></div>` : ''}
            ${chatBodyHtml(message.body)}<div class="bubble-time">${fmtMessageTimestamp(message.created_at)}</div>
          </div>
          ${chatMessageActionHtml(message, mine)}
        </div>`;
      }).join('');
      if (prepend) { msgsEl.querySelector('.empty-state')?.remove(); msgsEl.insertAdjacentHTML('afterbegin', html); }
      else if (append && !msgsEl.querySelector('.empty-state')) msgsEl.insertAdjacentHTML('beforeend', html);
      else if (append) msgsEl.innerHTML = html;
      else msgsEl.innerHTML = html || '<div class="empty-state" style="padding:20px">No messages yet — pick the next time.</div>';
      normalizeChatDaySeparators(msgsEl);
      chatUX.restoreScroll(snapshot, { forceBottom, newMessageCount: newMessages ? items.length : 0, preserveAnchor: prepend });
      hydrateChatImages(msgsEl, chatUX);
    };
    renderMessages(data.items || data.messages || [], false, { forceBottom: true });
    attachChatHistoryLoader(
      modal, msgsEl, data,
      (beforeId) => api(`/crews/${crew.id}/chat?before_id=${beforeId}&limit=60`),
      (items) => renderMessages(items, false, { prepend: true }),
    );
    chatUX.activateOutbox?.((message) => renderMessages([message], true, { forceBottom: true }));
    addPhotoToComposer(modal, '#crew-form', '#crew-text', chatUX);
    startAdaptiveChatPoll(modal, msgsEl, async () => {
      const fresh = await api(`/crews/${crew.id}/chat?since_id=${lastId}`);
      const items = fresh.items || fresh.messages || [];
      if (items.length) renderMessages(items, true, { newMessages: true });
      applyRoomHearts(msgsEl, fresh.heart_counts);
      return items.length > 0;
    });
    modal.querySelector('#crew-chat-head').addEventListener('click', (event) => {
      const infoButton = event.currentTarget;
      const modalIndex = overlayStack.findIndex((entry) => entry.el === modal);
      const parent = modalIndex > 0 ? overlayStack[modalIndex - 1]?.el : null;
      if (modal.classList.contains('flow-child-modal')
          && Number(parent?.dataset.crewInfoId) === Number(crew.id)) {
        dismissModal(modal);
        return;
      }
      const resetAction = beginButtonAction(infoButton, 'Opening info…');
      if (!resetAction) return;
      const opened = openChildModal(modal, () => openCrewScreen(crew.id));
      if (!opened) resetAction();
      else {
        const child = currentOverlayEntry()?.el;
        child?._cleanupFns?.push(() => {
          if (infoButton.isConnected) resetAction();
        });
      }
    });
    modal.querySelector('#crew-form').addEventListener('submit', async (event) => {
      event.preventDefault();
      const body = input.value.trim();
      if (!body) return;
      try { await chatUX.send?.(body); } catch (error) { toast(error.message); }
    });
    return modal;
  }

