  async function openClubScreen(clubId, { destination = 'info' } = {}) {
    const route = { kind: 'club', id: clubId };
    const shell = openDetailLoadShell({
      route,
      title: 'Opening community',
      copy: 'Loading members, upcoming play, and community details…',
      label: 'Loading community details',
    });
    if (!shell) return;
    const routeLoad = shell.load;
    let club;
    try { club = await api(`/clubs/${clubId}`); }
    catch (e) {
      if (!routedOverlayLoadIsCurrent(routeLoad) || !shell.modal.isConnected) return;
      if ([404, 410].includes(Number(e.status))) clearDeadDeepLink(`#club/${clubId}`);
      renderDetailLoadError(
        shell,
        e.message || 'This community could not load.',
        () => retryDetailLoad(shell, () => openClubScreen(clubId, { destination })),
        'Community details could not load',
      );
      return shell.modal;
    }
    if (!routedOverlayLoadIsCurrent(routeLoad) || !shell.modal.isConnected) return;
    // Entity links and deep links land on the useful info hub. Conversation
    // rows can explicitly request chat, keeping navigation intent honest.
    return transitionModal(shell.modal, () => (
      destination === 'chat' && club.joined ? openClubChat(club) : openClubInfo(club)
    ));
  }

